// The panel beside the chart: everything about one task that can be changed.
//
// All three editable renderers share it, which is what keeps them honest with
// each other - a bar dragged in vis and a date typed here are the same write to
// the same file, and none of the charts has an editing story of its own to get
// out of step. Every control makes a `GanttOp` and hands it up: the page runs
// it, pushes it on the undo stack and refetches, so nothing in this file knows
// what the plan looks like afterwards.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Input from '@mui/joy/Input';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import Divider from '@mui/joy/Divider';
import Tooltip from '@mui/joy/Tooltip';
import Chip from '@mui/joy/Chip';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import CloseIcon from '@mui/icons-material/Close';
import AddIcon from '@mui/icons-material/Add';
import KeyboardArrowRightIcon from '@mui/icons-material/KeyboardArrowRight';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import ChipDelete from '@mui/joy/ChipDelete';
import Autocomplete from '@mui/joy/Autocomplete';
import { GanttTask, dayKey, parseGanttDate } from '../gantt';
import {
    GanttOp, renameOp, statusOp, startOp, effortOp, colorOp, percentOp,
    sectionOp, orderOp, dependencyOp, deleteOp,
    setPropOp, renamePropOp, propNameError, tagsOp, tagError,
} from '../ganttops';
import { ODb } from '../db';
import { useSetting } from '../useSettings';

const SWATCHES = ['', '#4a90d9', '#2ecc71', '#e74c3c', '#f39c12', '#8e44ad', '#16a085', '#7f8c8d'];

export default function GanttInspector({
    task,
    tasks,
    statuses,
    busy,
    onRun,
    onClose,
}: {
    task: GanttTask;
    tasks: GanttTask[];
    statuses: string[];
    busy: boolean;
    // Ops are run in order and undone as one press when there is more than one.
    onRun: (ops: GanttOp[]) => void;
    onClose: () => void;
}) {
    const [name, setName] = React.useState(task.name);
    const [effort, setEffort] = React.useState(String(task.plannedDays ?? 1));
    const [section, setSection] = React.useState(task.section);
    const [order, setOrder] = React.useState(task.order === null || task.order === undefined ? '' : String(task.order));

    // The task can change under the panel - a drag in the chart, a refetch after
    // somebody else's edit - and the fields have to follow it, or a rename typed
    // here would post the name of the task that used to be selected.
    React.useEffect(() => {
        setName(task.name);
        setEffort(String(task.plannedDays ?? 1));
        setSection(task.section);
        setOrder(task.order === null || task.order === undefined ? '' : String(task.order));
    }, [task]);

    const editable = !task.implied && !!task.hash;
    const deps = tasks.filter(t => t.hash && t.hash !== task.hash && !t.implied);
    const dependsOn = task.after.length > 0 ? task.after[0] : '';

    const run = (op: GanttOp | null) => { if (op) onRun([op]); };

    return (
        <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 2, minWidth: 280, maxWidth: 340 }}>
            <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, mb: 1 }}>
                <Box sx={{ flex: 1, minWidth: 0 }}>
                    <Typography level="title-sm" sx={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>
                        {task.name}
                    </Typography>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        {task.filename ? task.filename.split('/').pop() : ''}
                        {task.lineNum ? `:${task.lineNum}` : ''}
                    </Typography>
                </Box>
                <IconButton size="sm" variant="plain" onClick={onClose}><CloseIcon /></IconButton>
            </Box>

            {task.implied && (
                <Chip size="sm" color="neutral" variant="soft" sx={{ mb: 1 }}>
                    Not in this query - shown because something here waits on it
                </Chip>
            )}

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
                <FormControl size="sm">
                    <FormLabel>Name</FormLabel>
                    <Input
                        size="sm"
                        value={name}
                        disabled={!editable || busy}
                        onChange={e => setName(e.target.value)}
                        // Found by the chart's Enter key, which comes here to rename.
                        slotProps={{ input: { 'data-gantt-rename': '1' } as any }}
                        onKeyDown={e => { if (e.key === 'Enter' && name !== task.name) run(renameOp(task, name)); }}
                        onBlur={() => { if (name !== task.name && name.trim() !== '') run(renameOp(task, name.trim())); }}
                    />
                </FormControl>

                <Box sx={{ display: 'flex', gap: 1 }}>
                    <FormControl size="sm" sx={{ flex: 1 }}>
                        <FormLabel>Keyword</FormLabel>
                        <Select
                            size="sm"
                            value={task.status || ''}
                            disabled={!editable || busy}
                            onChange={(_e, v) => { if (v !== null && v !== (task.status || '')) run(statusOp(task, v as string)); }}
                        >
                            {['', ...statuses.filter(Boolean)].map(s => (
                                <Option key={s || 'none'} value={s}>{s || '(none)'}</Option>
                            ))}
                        </Select>
                    </FormControl>
                    <FormControl size="sm" sx={{ width: 96 }}>
                        <FormLabel>Done %</FormLabel>
                        <Input
                            size="sm" type="number" slotProps={{ input: { min: 0, max: 100, step: 5 } }}
                            defaultValue={task.percent ?? 0}
                            disabled={!editable || busy}
                            onBlur={e => {
                                const v = Number(e.target.value);
                                if (!isNaN(v) && v !== (task.percent ?? 0)) run(percentOp(task, v));
                            }}
                        />
                    </FormControl>
                </Box>

                <Box sx={{ display: 'flex', gap: 1 }}>
                    <FormControl size="sm" sx={{ flex: 1 }}>
                        <FormLabel>{task.dateKind === 'TIMESTAMP' ? 'Timestamp' : 'Scheduled'}</FormLabel>
                        <Input
                            size="sm" type="date"
                            value={task.dated ? dayKey(task.start) : ''}
                            disabled={!editable || busy}
                            onChange={e => {
                                const d = e.target.value ? parseGanttDate(e.target.value) : null;
                                run(startOp(task, d));
                            }}
                        />
                    </FormControl>
                    <FormControl size="sm" sx={{ width: 96 }}>
                        <FormLabel>Effort (d)</FormLabel>
                        <Input
                            size="sm" type="number" slotProps={{ input: { min: 0.1, step: 0.5 } }}
                            value={effort}
                            disabled={!editable || busy}
                            onChange={e => setEffort(e.target.value)}
                            onBlur={() => {
                                const v = Number(effort);
                                if (!isNaN(v) && v > 0 && v !== task.plannedDays) run(effortOp(task, v));
                            }}
                        />
                    </FormControl>
                </Box>
                {!task.dated && editable && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: -1 }}>
                        No date of its own - it sits where it does because of what it comes after.
                    </Typography>
                )}

                <FormControl size="sm">
                    <FormLabel>Comes after</FormLabel>
                    <Select
                        size="sm"
                        value={dependsOn}
                        disabled={!editable || busy}
                        onChange={(_e, v) => {
                            const next = (v as string) || '';
                            if (next === dependsOn) return;
                            const dep = next ? deps.find(d => d.hash === next) || null : null;
                            const { op, ensureId } = dependencyOp(task, dep);
                            onRun(ensureId ? [ensureId, op] : [op]);
                        }}
                    >
                        <Option value="">(nothing)</Option>
                        {deps.map(d => (
                            <Option key={d.hash} value={d.hash as string}>{d.name}</Option>
                        ))}
                    </Select>
                </FormControl>

                <Box sx={{ display: 'flex', gap: 1 }}>
                    <FormControl size="sm" sx={{ flex: 1 }}>
                        <FormLabel>Lane</FormLabel>
                        <Input
                            size="sm" value={section} disabled={!editable || busy}
                            onChange={e => setSection(e.target.value)}
                            onBlur={() => { if (section !== task.section) run(sectionOp(task, section)); }}
                        />
                    </FormControl>
                    <FormControl size="sm" sx={{ width: 96 }}>
                        <FormLabel>Row order</FormLabel>
                        <Input
                            size="sm" type="number" value={order} disabled={!editable || busy}
                            onChange={e => setOrder(e.target.value)}
                            onBlur={() => {
                                const v = Number(order);
                                if (order !== '' && !isNaN(v) && v !== task.order) run(orderOp(task, v));
                            }}
                        />
                    </FormControl>
                </Box>

                <FormControl size="sm">
                    <FormLabel>Colour</FormLabel>
                    <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', alignItems: 'center' }}>
                        {SWATCHES.map(c => (
                            <Tooltip key={c || 'lane'} size="sm" title={c || 'the lane colour'}>
                                <Box
                                    onClick={() => { if (editable && !busy && c !== (task.color || '')) run(colorOp(task, c)); }}
                                    sx={{
                                        width: 22, height: 22, borderRadius: '4px', cursor: editable ? 'pointer' : 'default',
                                        bgcolor: c || 'transparent',
                                        border: '2px solid',
                                        borderColor: (task.color || '') === c ? 'primary.500' : 'neutral.400',
                                        backgroundImage: c ? 'none' : 'repeating-linear-gradient(45deg, #ccc 0 4px, #fff 4px 8px)',
                                    }}
                                />
                            </Tooltip>
                        ))}
                        <input
                            type="color"
                            value={task.color || '#4a90d9'}
                            disabled={!editable || busy}
                            onChange={e => run(colorOp(task, e.target.value))}
                            style={{ width: 26, height: 26, border: 'none', background: 'none', padding: 0, cursor: 'pointer' }}
                        />
                    </Box>
                </FormControl>

                <TagEditor task={task} disabled={!editable || busy} onRun={onRun} />

                <PropertyFoldout task={task} disabled={!editable || busy} onRun={onRun} />

                <Divider />
                <Button
                    size="sm" variant="soft" color="danger" startDecorator={<DeleteOutlineIcon />}
                    disabled={!editable || busy}
                    onClick={() => run(deleteOp(task))}
                >
                    Delete task
                </Button>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    Deleting takes the whole heading. Undo puts the words back as a new
                    heading, not the same one.
                </Typography>
            </Box>
        </Sheet>
    );
}

// --- tags -------------------------------------------------------------------

// Every tag the server knows, asked for once per page rather than once per
// task selected: it only feeds the suggestions, and a tag typed that is not in
// it is simply a new tag.
let knownTags: Promise<string[]> | null = null;
function allTags(): Promise<string[]> {
    if (!knownTags) knownTags = ODb.getAllTags().then(t => t || []).catch(() => { knownTags = null; return []; });
    return knownTags;
}

// The heading's own tags, as chips: the cross takes one off, the box puts one
// on (picked from the known tags or typed and Enter). Each change is one write
// of the whole list and one undo.
function TagEditor({ task, disabled, onRun }: {
    task: GanttTask;
    disabled: boolean;
    onRun: (ops: GanttOp[]) => void;
}) {
    const tags = task.tags || [];
    const [known, setKnown] = React.useState<string[]>([]);
    const [text, setText] = React.useState('');
    const [err, setErr] = React.useState('');
    React.useEffect(() => { let alive = true; allTags().then(t => { if (alive) setKnown(t); }); return () => { alive = false; }; }, []);

    const add = (raw: string | null) => {
        const t = (raw || '').trim().replace(/^:+|:+$/g, '');
        if (!t) return;
        const bad = tagError(t);
        if (bad) { setErr(bad); return; }
        setErr('');
        setText('');
        if (tags.indexOf(t) >= 0) return;
        onRun([tagsOp(task, [...tags, t])]);
    };

    return (
        <FormControl size="sm" error={!!err}>
            <FormLabel>Tags</FormLabel>
            {tags.length > 0 && (
                <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mb: 0.75 }}>
                    {tags.map(t => (
                        <Chip
                            key={t} size="sm" variant="soft"
                            endDecorator={disabled ? undefined : (
                                <ChipDelete aria-label={`remove ${t}`} onDelete={() => onRun([tagsOp(task, tags.filter(x => x !== t))])} />
                            )}
                        >
                            {t}
                        </Chip>
                    ))}
                </Box>
            )}
            <Autocomplete
                size="sm"
                freeSolo
                placeholder="Add a tag"
                disabled={disabled}
                options={known.filter(k => tags.indexOf(k) < 0)}
                value={null}
                inputValue={text}
                onInputChange={(_e, v) => { setText(v); if (err) setErr(''); }}
                onChange={(_e, v) => add(typeof v === 'string' ? v : null)}
                blurOnSelect={false}
                clearOnBlur={false}
            />
            {err && <Typography level="body-xs" color="danger">{err}</Typography>}
        </FormControl>
    );
}

// --- properties ---------------------------------------------------------------

// The heading's property drawer, folded away by default. Every row is the
// property's name and value, both editable: a row is written when focus leaves
// it (or on Enter), so tabbing from the name to the value does not write a
// rename half way. Emptying a value removes the property, as the cross does.
function PropertyFoldout({ task, disabled, onRun }: {
    task: GanttTask;
    disabled: boolean;
    onRun: (ops: GanttOp[]) => void;
}) {
    const [open, setOpen] = useSetting('ganttInspectorProps');
    const props = Object.entries(task.props || {});
    return (
        <Box>
            <Button
                size="sm" variant="plain" color="neutral"
                startDecorator={open ? <KeyboardArrowDownIcon /> : <KeyboardArrowRightIcon />}
                onClick={() => setOpen(!open)}
                sx={{ px: 0.5, ml: -0.5, fontWeight: 'md' }}
            >
                Properties ({props.length})
            </Button>
            {open && (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.75, mt: 0.5 }}>
                    {props.map(([k, v]) => (
                        <PropertyRow key={k} task={task} name={k} value={v} disabled={disabled} onRun={onRun} />
                    ))}
                    {props.length === 0 && (
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>No properties yet.</Typography>
                    )}
                    <NewProperty task={task} disabled={disabled} onRun={onRun} />
                </Box>
            )}
        </Box>
    );
}

function PropertyRow({ task, name, value, disabled, onRun }: {
    task: GanttTask;
    name: string;
    value: string;
    disabled: boolean;
    onRun: (ops: GanttOp[]) => void;
}) {
    const [k, setK] = React.useState(name);
    const [v, setV] = React.useState(value);
    const [err, setErr] = React.useState('');
    // A refetch after an edit elsewhere (or an undo) brings a new value in.
    React.useEffect(() => { setK(name); setV(value); setErr(''); }, [name, value]);

    const reset = () => { setK(name); setV(value); setErr(''); };
    const commit = () => {
        const nk = k.trim();
        const nv = v.trim();
        if (nk === name && nv === value) return;
        if (nv === '') { onRun([setPropOp(task, name, '')]); return; }
        if (nk !== name) {
            const bad = propNameError(nk);
            if (bad) { setErr(bad); return; }
            const taken = Object.keys(task.props || {}).some(x => x !== name && x.toUpperCase() === nk.toUpperCase());
            if (taken) { setErr(`there is already a ${nk}`); return; }
            onRun(renamePropOp(task, name, nk, nv));
            return;
        }
        onRun([setPropOp(task, name, nv)]);
    };
    const keys = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') commit();
        else if (e.key === 'Escape') reset();
    };

    return (
        <Box
            onBlur={e => { if (!e.currentTarget.contains(e.relatedTarget as Node | null)) commit(); }}
        >
            <Box sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
                <Input
                    size="sm" value={k} disabled={disabled} error={!!err}
                    onChange={e => { setK(e.target.value); setErr(''); }} onKeyDown={keys}
                    sx={{ width: 112, fontFamily: 'code', fontSize: 'xs' }}
                />
                <Input
                    size="sm" value={v} disabled={disabled} placeholder="(remove)"
                    onChange={e => setV(e.target.value)} onKeyDown={keys}
                    sx={{ flex: 1, minWidth: 0 }}
                />
                <Tooltip size="sm" title={`Remove ${name}`}>
                    <span>
                        <IconButton
                            size="sm" variant="plain" color="neutral" disabled={disabled}
                            onClick={() => onRun([setPropOp(task, name, '')])}
                        >
                            <DeleteOutlineIcon />
                        </IconButton>
                    </span>
                </Tooltip>
            </Box>
            {err && <Typography level="body-xs" color="danger">{err}</Typography>}
        </Box>
    );
}

function NewProperty({ task, disabled, onRun }: {
    task: GanttTask;
    disabled: boolean;
    onRun: (ops: GanttOp[]) => void;
}) {
    const [k, setK] = React.useState('');
    const [v, setV] = React.useState('');
    const [err, setErr] = React.useState('');
    const nameRef = React.useRef<HTMLInputElement>(null);
    React.useEffect(() => { setK(''); setV(''); setErr(''); }, [task.hash]);

    const add = () => {
        const nk = k.trim();
        const nv = v.trim();
        const bad = propNameError(nk);
        if (bad) { setErr(bad); return; }
        if (Object.keys(task.props || {}).some(x => x.toUpperCase() === nk.toUpperCase())) {
            setErr(`there is already a ${nk} - change it above`);
            return;
        }
        if (!nv) { setErr('a property needs a value - an empty one is no property'); return; }
        onRun([setPropOp(task, nk, nv)]);
        setK(''); setV(''); setErr('');
        nameRef.current?.focus();
    };
    const keys = (e: React.KeyboardEvent) => { if (e.key === 'Enter') add(); };

    return (
        <Box>
            <Box sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
                <Input
                    size="sm" value={k} disabled={disabled} placeholder="NAME" error={!!err}
                    slotProps={{ input: { ref: nameRef } }}
                    onChange={e => { setK(e.target.value); setErr(''); }} onKeyDown={keys}
                    sx={{ width: 112, fontFamily: 'code', fontSize: 'xs' }}
                />
                <Input
                    size="sm" value={v} disabled={disabled} placeholder="value"
                    onChange={e => { setV(e.target.value); setErr(''); }} onKeyDown={keys}
                    sx={{ flex: 1, minWidth: 0 }}
                />
                <Tooltip size="sm" title="Add property">
                    <span>
                        <IconButton size="sm" variant="soft" disabled={disabled || !k.trim()} onClick={add}>
                            <AddIcon />
                        </IconButton>
                    </span>
                </Tooltip>
            </Box>
            {err && <Typography level="body-xs" color="danger">{err}</Typography>}
        </Box>
    );
}
