// Generating marker sets: a regular expression over tags or a property's
// values, the matches shown grouped by the value they share, and a marker set
// made for each group chosen - so M1, M2 and M3 milestones, or every RELEASE,
// each get their own colour and can be styled apart. The arithmetic (grouping,
// the queries written, escaping) is markersets.ts.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import Input from '@mui/joy/Input';
import Checkbox from '@mui/joy/Checkbox';
import Divider from '@mui/joy/Divider';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import RadioGroup from '@mui/joy/RadioGroup';
import Radio from '@mui/joy/Radio';
import { ODb } from '../db';
import { MarkerSet, MatchResult, groupMatches, matchQuery, setsFor } from '../markersets';
import { categorical } from '../ganttstyle';

export default function MarkerSetGenerator({ open, onClose, onGenerate, startColor, props, tags }: {
    open: boolean;
    onClose: () => void;
    onGenerate: (sets: MarkerSet[]) => void;
    // Where the colours start, so new sets do not repeat the view's.
    startColor: number;
    // Property names and tags seen on the chart, offered while typing.
    props: string[];
    tags: string[];
}) {
    const [source, setSource] = React.useState<'tag' | 'prop'>('tag');
    const [prop, setProp] = React.useState('');
    const [pattern, setPattern] = React.useState('');
    const [result, setResult] = React.useState<MatchResult | null>(null);
    const [chosen, setChosen] = React.useState<Set<string>>(new Set());
    const [looking, setLooking] = React.useState(false);
    const [error, setError] = React.useState('');

    // A pattern that does not compile is said so as it is typed, not after
    // a round trip.
    const re = React.useMemo((): RegExp | null => {
        if (!pattern) return null;
        try { return new RegExp(pattern); } catch { return null; }
    }, [pattern]);
    const patternError = pattern && !re ? 'Not a regular expression yet' : '';

    React.useEffect(() => { setResult(null); setError(''); }, [source, prop, pattern]);

    const show = async () => {
        if (!re || (source === 'prop' && !prop.trim())) return;
        setLooking(true);
        setError('');
        try {
            const rows = await ODb.query(matchQuery(source, prop.trim(), pattern), false, null as any, '');
            if (!Array.isArray(rows)) {
                // The server's own regular expressions (Go's) refuse a few
                // things a browser allows, such as look-behind.
                setError(((rows as any) && (rows as any).Msg) || 'the server could not run that pattern');
                setResult(null);
            } else {
                const r = groupMatches(rows, source, prop.trim(), re);
                setResult(r);
                setChosen(new Set(r.groups.filter(g => g.dated.length > 0).map(g => g.key)));
            }
        } catch (e: any) {
            setError(e.message || 'the search failed');
        }
        setLooking(false);
    };

    const generate = () => {
        if (!result) return;
        const groups = result.groups.filter(g => chosen.has(g.key));
        onGenerate(setsFor(source, prop.trim(), groups, startColor));
    };

    if (!open) return null;
    const chosenCount = result ? result.groups.filter(g => chosen.has(g.key)).length : 0;
    let colorAt = startColor;

    return (
        <Modal open onClose={(_e, reason) => { if (reason !== 'backdropClick') onClose(); }}
            slotProps={{ backdrop: { sx: { backdropFilter: 'none', backgroundColor: 'transparent' } } }}>
            <ModalDialog sx={{ width: 560, maxWidth: '96vw', top: 72, right: 24, left: 'auto', transform: 'none',
                maxHeight: 'calc(100dvh - 96px)', overflowY: 'auto', boxShadow: 'xl' }}>
                <Typography level="title-md">Generate marker sets</Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    A set of markers for each value a pattern picks out of your tags or a property - each set
                    its own query, colour and style, to change one at a time afterwards. A capture group
                    names the set by part of the value: <code>^(M\d+)-</code> puts M1-alpha and M1-beta in one set, M1.
                </Typography>
                <Divider sx={{ my: 1 }} />
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.25 }}>
                    <RadioGroup orientation="horizontal" value={source}
                        onChange={e => setSource(e.target.value as 'tag' | 'prop')} sx={{ gap: 2 }}>
                        <Radio size="sm" value="tag" label="Tags" />
                        <Radio size="sm" value="prop" label="A property's values" />
                    </RadioGroup>
                    <Box sx={{ display: 'flex', gap: 1, alignItems: 'flex-end', flexWrap: 'wrap' }}>
                        {source === 'prop' && (
                            <FormControl size="sm">
                                <FormLabel>Property</FormLabel>
                                <Input size="sm" value={prop} onChange={e => setProp(e.target.value.toUpperCase())}
                                    placeholder="RELEASE" sx={{ width: 150 }}
                                    slotProps={{ input: { list: 'gen-props', 'aria-label': 'Property' } }} />
                                <datalist id="gen-props">{props.map(p => <option key={p} value={p} />)}</datalist>
                            </FormControl>
                        )}
                        <FormControl size="sm" sx={{ flex: 1, minWidth: 200 }}>
                            <FormLabel>Pattern (regular expression)</FormLabel>
                            <Input size="sm" value={pattern} onChange={e => setPattern(e.target.value)}
                                placeholder={source === 'tag' ? '^M\\d+$' : '^(\\d+\\.\\d+)'}
                                onKeyDown={e => { if (e.key === 'Enter') show(); }}
                                color={patternError ? 'danger' : 'neutral'}
                                sx={{ fontFamily: 'monospace' }}
                                slotProps={{ input: { 'aria-label': 'Pattern', spellCheck: false } }} />
                        </FormControl>
                        <Button size="sm" variant="outlined" loading={looking}
                            disabled={!re || (source === 'prop' && !prop.trim())} onClick={show}>
                            Show matches
                        </Button>
                    </Box>
                    {source === 'tag' && tags.length > 0 && !pattern && (
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {`Tags on this chart: ${tags.slice(0, 12).join(' ')}${tags.length > 12 ? ' …' : ''}`}
                        </Typography>
                    )}
                    {(patternError || error) && (
                        <Typography level="body-xs" sx={{ color: 'danger.500' }}>{patternError || error}</Typography>
                    )}

                    {result && (
                        <Box data-testid="gen-matches">
                            {result.groups.length === 0 ? (
                                <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>Nothing matches.</Typography>
                            ) : (
                                <>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                                        <Typography level="body-xs" sx={{ color: 'text.tertiary', flex: 1 }}>
                                            {`${result.groups.length} value${result.groups.length === 1 ? '' : 's'} - only headings with a date become markers`}
                                        </Typography>
                                        <Button size="sm" variant="plain"
                                            onClick={() => setChosen(new Set(result.groups.filter(g => g.dated.length > 0).map(g => g.key)))}>
                                            All
                                        </Button>
                                        <Button size="sm" variant="plain" onClick={() => setChosen(new Set())}>None</Button>
                                    </Box>
                                    <Box sx={{ border: '1px solid', borderColor: 'neutral.outlinedBorder', borderRadius: 'sm',
                                        maxHeight: 300, overflowY: 'auto' }}>
                                        {result.groups.map(g => {
                                            const on = chosen.has(g.key);
                                            const color = on ? categorical(colorAt++) : undefined;
                                            return (
                                                <Box key={g.key} sx={{ display: 'flex', gap: 1, alignItems: 'flex-start', px: 1, py: 0.75,
                                                    borderBottom: '1px solid', borderColor: 'divider', opacity: g.dated.length ? 1 : 0.6 }}>
                                                    <Checkbox size="sm" checked={on} disabled={g.dated.length === 0}
                                                        onChange={e => setChosen(prev => {
                                                            const next = new Set(prev);
                                                            if (e.target.checked) next.add(g.key); else next.delete(g.key);
                                                            return next;
                                                        })}
                                                        slotProps={{ input: { 'aria-label': `Make a set for ${g.key}` } }} />
                                                    <Box sx={{ width: 12, height: 12, borderRadius: '3px', mt: 0.4, flexShrink: 0,
                                                        bgcolor: color || 'neutral.300' }} />
                                                    <Box sx={{ flex: 1, minWidth: 0 }}>
                                                        <Typography level="body-sm" sx={{ fontWeight: 600 }}>
                                                            {g.key}
                                                            {g.values.length > 1 && (
                                                                <Typography component="span" level="body-xs" sx={{ color: 'text.tertiary', ml: 1, fontWeight: 400 }}>
                                                                    {g.values.join(', ')}
                                                                </Typography>
                                                            )}
                                                        </Typography>
                                                        <Typography level="body-xs" sx={{ color: 'text.secondary' }} noWrap>
                                                            {g.dated.length > 0
                                                                ? `${g.dated.length} dated: ${g.dated.slice(0, 6).join(', ')}${g.dated.length > 6 ? ' …' : ''}`
                                                                : 'no heading here has a date - nothing to draw'}
                                                        </Typography>
                                                        {g.undated.length > 0 && (
                                                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }} noWrap>
                                                                {`${g.undated.length} without a date: ${g.undated.slice(0, 4).join(', ')}${g.undated.length > 4 ? ' …' : ''}`}
                                                            </Typography>
                                                        )}
                                                    </Box>
                                                </Box>
                                            );
                                        })}
                                    </Box>
                                    {result.inherited.length > 0 && (
                                        <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 0.5 }}>
                                            {`${result.inherited.length} more match only through a parent's or the file's tags: ${result.inherited.slice(0, 4).join(', ')}${result.inherited.length > 4 ? ' …' : ''}. Each set's query finds those too.`}
                                        </Typography>
                                    )}
                                </>
                            )}
                        </Box>
                    )}

                    <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 0.5 }}>
                        <Button size="sm" variant="plain" onClick={onClose}>Cancel</Button>
                        <Button size="sm" disabled={!result || chosenCount === 0} onClick={generate}>
                            {chosenCount > 0 ? `Generate ${chosenCount} set${chosenCount === 1 ? '' : 's'}` : 'Generate'}
                        </Button>
                    </Box>
                </Box>
            </ModalDialog>
        </Modal>
    );
}
