import * as React from 'react';
import Box from '@mui/joy/Box';
import Button from '@mui/joy/Button';
import Chip from '@mui/joy/Chip';
import IconButton from '@mui/joy/IconButton';
import Option from '@mui/joy/Option';
import Select from '@mui/joy/Select';
import Tooltip from '@mui/joy/Tooltip';
import Typography from '@mui/joy/Typography';
import ToggleButtonGroup from '@mui/joy/ToggleButtonGroup';
import { useColorScheme } from '@mui/joy/styles';
import ViewColumnOutlinedIcon from '@mui/icons-material/ViewColumnOutlined';
import ViewStreamOutlinedIcon from '@mui/icons-material/ViewStreamOutlined';
import AccountTreeOutlinedIcon from '@mui/icons-material/AccountTreeOutlined';
import KeyboardArrowUpIcon from '@mui/icons-material/KeyboardArrowUp';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import WrapTextIcon from '@mui/icons-material/WrapText';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import SpaceBarIcon from '@mui/icons-material/SpaceBar';
import UnfoldMoreIcon from '@mui/icons-material/UnfoldMore';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';

import { useSetting } from '../useSettings';
import { orgPalette, Palette } from '../orgtheme';
import { lineTokens, walk, todoStates, LineState, TodoStates } from './OrgSource';
import { isTyping } from './Capture';
import { useIsMobile } from '../useMobile';
import {
    splitLines, diffLines, diffStats, buildRows, unifiedRows, foldRows, wordDiff, parseOutline,
    headingPathAt, outlineDiff, toPatch, Row, UniRow, Span, Heading, OutlineDiff,
} from '../orgdiff';
import DiffOutline from './DiffOutline';
import DiffSummary from './DiffSummary';

// One side of a comparison: the text, and how to name it.
export type DiffSide = {
    text: string;
    label: string;   // "a3f2c1d", "Working copy", "notes.org"
    detail?: string; // the commit's subject, a path
    missing?: boolean;
};

const MONO = '"SFMono-Regular", "JetBrains Mono", Consolas, "Liberation Mono", Menlo, monospace';

// The colours of a diff, made from the reader's org theme so the panes look
// like the Org view they are comparing, whichever of the eleven schemes that
// is. Washes for a whole line, a stronger tint for the words that changed.
export function diffColors(p: Palette, dark: boolean) {
    const green = p.checkDone || '#3fb950';
    const red = p.todo || '#f85149';
    return {
        addLine: alpha(green, dark ? 0.13 : 0.11),
        addWord: alpha(green, dark ? 0.38 : 0.3),
        addGutter: alpha(green, dark ? 0.22 : 0.18),
        addInk: green,
        delLine: alpha(red, dark ? 0.13 : 0.09),
        delWord: alpha(red, dark ? 0.38 : 0.26),
        delGutter: alpha(red, dark ? 0.22 : 0.16),
        delInk: red,
        modInk: p.planning || '#d29922',
        filler: alpha(p.gutter, dark ? 0.16 : 0.14),
        foldBg: alpha(p.tsActive || p.fg, dark ? 0.08 : 0.07),
        foldInk: p.tsActive || p.fg,
        current: p.h1,
    };
}

export function alpha(color: string, a: number): string {
    const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(color.trim());
    if (!m) return color;
    const hex = m[1].length === 3 ? m[1].split('').map(c => c + c).join('') : m[1];
    const n = parseInt(hex, 16);
    return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

// A line painted: the org colouring the Org view gives it, with the spans that
// changed laid over it as a tint. The tokens are cut at the span edges so a
// changed day inside a timestamp keeps the timestamp's colour.
function Painted({ line, state, st, spans, tint, p }: {
    line: string; state: LineState | undefined; st: TodoStates; spans: Span[] | null; tint: string; p: Palette;
}) {
    const toks = state
        ? lineTokens(line, st, state.block, state.drawer, state.lang, { ...state.code })
        : [{ c: 'fg', s: line }];
    const out: React.ReactNode[] = [];
    let at = 0;
    let si = 0;
    toks.forEach((t, ti) => {
        let s = t.s;
        let start = at;
        const style = {
            color: p[t.c] || p.fg,
            fontWeight: t.bold ? 700 : undefined,
            fontStyle: t.italic ? 'italic' : undefined,
            textDecoration: t.strike ? 'line-through' : t.underline ? 'underline' : undefined,
        } as React.CSSProperties;
        while (s.length > 0) {
            while (spans && si < spans.length && spans[si][1] <= start) si++;
            const sp = spans && si < spans.length ? spans[si] : null;
            let cut = s.length;
            let inSpan = false;
            if (sp) {
                if (sp[0] <= start) { inSpan = true; cut = Math.min(s.length, sp[1] - start); }
                else cut = Math.min(s.length, sp[0] - start);
            }
            const piece = s.slice(0, cut);
            out.push(
                <span key={`${ti}-${start}`} style={inSpan ? { ...style, backgroundColor: tint, borderRadius: 2 } : style}>
                    {piece}
                </span>,
            );
            s = s.slice(cut);
            start += cut;
        }
        at += t.s.length;
    });
    if (line === '') out.push('​');
    return <>{out}</>;
}

// How many rows to draw at first, and how many more as the reader nears the
// bottom: a whole-file view of a long file is thousands of rows.
const CHUNK = 1200;

type Props = {
    left: DiffSide;
    right: DiffSide;
    // Shown above the panes when nothing is loaded or something failed.
    placeholder?: React.ReactNode;
    loading?: boolean;
};

export default function DiffView({ left, right, placeholder, loading }: Props) {
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';
    const [themeKey] = useSetting('orgTheme');
    const p = orgPalette(themeKey, dark);
    const col = diffColors(p, dark);
    const isMobile = useIsMobile();

    const [view, setView] = useSetting('diffView');
    const [wrap, setWrap] = useSetting('diffWrap');
    const [context, setContext] = useSetting('diffContext');
    const [ignoreWs, setIgnoreWs] = useSetting('diffIgnoreWs');
    // Side by side needs the width; a phone gets the unified view.
    const shownView = isMobile && view === 'split' ? 'unified' : view;

    const a = React.useMemo(() => splitLines(left.text), [left.text]);
    const b = React.useMemo(() => splitLines(right.text), [right.text]);
    const st = React.useMemo(() => todoStates(left.text + '\n' + right.text), [left.text, right.text]);
    const aStates = React.useMemo(() => walk(a), [a]);
    const bStates = React.useMemo(() => walk(b), [b]);
    const aOutline = React.useMemo<Heading[]>(() => parseOutline(left.text, st), [left.text, st]);
    const bOutline = React.useMemo<Heading[]>(() => parseOutline(right.text, st), [right.text, st]);

    const chunks = React.useMemo(() => diffLines(a, b, { ignoreWhitespace: ignoreWs }), [a, b, ignoreWs]);
    const stats = React.useMemo(() => diffStats(chunks), [chunks]);
    const rows = React.useMemo(() => buildRows(chunks, a, b), [chunks, a, b]);
    const uni = React.useMemo(() => unifiedRows(rows), [rows]);
    const outline = React.useMemo<OutlineDiff>(
        () => outlineDiff(left.text, right.text, { ignoreWhitespace: ignoreWs }),
        [left.text, right.text, ignoreWs],
    );
    // The change chunks, in order: what next and previous step through.
    const changeChunks = React.useMemo(
        () => chunks.map((c, i) => (c.kind === 'change' ? i : -1)).filter(i => i >= 0),
        [chunks],
    );

    // Opened folds, keyed by the first row they hide. Forgotten when the
    // comparison changes, because the rows are different rows.
    const [expanded, setExpanded] = React.useState<Set<number>>(new Set());
    React.useEffect(() => { setExpanded(new Set()); }, [rows, uni, shownView]);
    const list: (Row | UniRow)[] = shownView === 'unified' ? uni : rows;
    const shown = React.useMemo(
        () => foldRows<Row | UniRow>(list, context, expanded),
        [list, context, expanded],
    );

    const [limit, setLimit] = React.useState(CHUNK);
    React.useEffect(() => { setLimit(CHUNK); }, [shown]);

    // The change being looked at, by position in changeChunks.
    const [current, setCurrent] = React.useState(-1);
    React.useEffect(() => { setCurrent(-1); }, [chunks]);
    const scroller = React.useRef<HTMLDivElement | null>(null);
    const flash = alpha(col.current, 0.45);
    const [pendingScroll, setPendingScroll] = React.useState<{ chunk?: number; row?: number } | null>(null);

    const goTo = React.useCallback((k: number) => {
        if (changeChunks.length === 0) return;
        const n = ((k % changeChunks.length) + changeChunks.length) % changeChunks.length;
        setCurrent(n);
        const chunk = changeChunks[n];
        // Draw far enough down to reach it.
        const at = shown.findIndex(s => !('fold' in s) && s.row.chunk === chunk);
        if (at >= limit) setLimit(at + CHUNK);
        setPendingScroll({ chunk });
    }, [changeChunks, shown, limit]);

    React.useEffect(() => {
        if (!pendingScroll || !scroller.current) return;
        const sel = pendingScroll.chunk !== undefined
            ? `[data-chunk="${pendingScroll.chunk}"]`
            : `[data-row="${pendingScroll.row}"]`;
        const el = scroller.current.querySelector(sel) as HTMLElement | null;
        if (el) {
            el.scrollIntoView({ block: 'center', behavior: 'smooth' });
            if (pendingScroll.row !== undefined) {
                el.animate?.([{ backgroundColor: flash }, { backgroundColor: 'transparent' }], { duration: 1400 });
            }
        }
        setPendingScroll(null);
    }, [pendingScroll, shown, limit, flash]);

    // n / p, or j / k, step through the changes, as they do in most diff
    // tools; ignored while something is being typed into.
    React.useEffect(() => {
        const onKey = (e: KeyboardEvent) => {
            if (e.metaKey || e.ctrlKey || e.altKey || isTyping(e.target)) return;
            if (document.querySelector('.MuiModal-root')) return;
            if (e.key === 'n' || e.key === 'j') { e.preventDefault(); goTo(current + 1); }
            else if (e.key === 'p' || e.key === 'k') { e.preventDefault(); goTo(current - 1); }
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [goTo, current]);

    // From the outline: open the text views at a heading.
    const jumpToLine = React.useCallback((side: 'a' | 'b', line: number) => {
        const target = shownView === 'outline' ? (isMobile ? 'unified' : 'split') : shownView;
        if (shownView === 'outline') setView(target === 'split' ? 'split' : 'unified');
        const rowsNow: (Row | UniRow)[] = target === 'unified' ? uni : rows;
        const idx = rowsNow.findIndex(r => (side === 'b' ? r.b === line : r.a === line));
        if (idx < 0) return;
        // Open whichever fold hides it.
        const folds = foldRows<Row | UniRow>(rowsNow, context, expanded);
        const f = folds.find(s => 'fold' in s && idx >= s.from && idx < s.to) as { from: number } | undefined;
        if (f) setExpanded(prev => new Set(prev).add(f.from));
        setLimit(l => Math.max(l, idx + CHUNK));
        setPendingScroll({ row: idx });
    }, [shownView, isMobile, setView, uni, rows, context, expanded]);

    const [copied, setCopied] = React.useState(false);
    const copyPatch = () => {
        const patch = toPatch(chunks, a, b, `a/${left.label}`, `b/${right.label}`);
        navigator.clipboard?.writeText(patch).then(() => {
            setCopied(true);
            window.setTimeout(() => setCopied(false), 1500);
        });
    };

    const onScroll = (e: React.UIEvent<HTMLDivElement>) => {
        if (limit >= shown.length) return;
        const el = e.currentTarget;
        if (el.scrollTop + el.clientHeight * 2 < el.scrollHeight) return;
        setLimit(n => Math.min(shown.length, n + CHUNK));
    };

    const identical = stats.changes === 0;
    const nothing = left.text === '' && right.text === '' && !left.missing && !right.missing;
    const gutterCh = String(Math.max(a.length, b.length, 1)).length + 1;

    // The heading a fold's following change sits under, so the band reads
    // "42 unchanged lines · Projects › Website redesign".
    const pathAfter = (to: number): string[] => {
        const r = list[to];
        if (!r) return [];
        if (r.b !== null) return headingPathAt(bOutline, r.b);
        if (r.a !== null) return headingPathAt(aOutline, r.a);
        return [];
    };

    const foldBand = (s: { from: number; to: number }, span: string) => {
        const path = pathAfter(s.to);
        return (
            <Box
                key={`fold-${s.from}`}
                onClick={() => setExpanded(prev => new Set(prev).add(s.from))}
                role="button"
                tabIndex={0}
                onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setExpanded(prev => new Set(prev).add(s.from)); } }}
                sx={{
                    gridColumn: span,
                    display: 'flex', alignItems: 'center', gap: 1,
                    px: 1.5, py: 0.4, my: 0.25,
                    bgcolor: col.foldBg, color: col.foldInk,
                    fontFamily: 'var(--joy-fontFamily-body)', fontSize: 12,
                    cursor: 'pointer', userSelect: 'none',
                    borderTop: `1px dashed ${alpha(col.foldInk, 0.25)}`,
                    borderBottom: `1px dashed ${alpha(col.foldInk, 0.25)}`,
                    '&:hover': { bgcolor: alpha(col.foldInk, 0.14) },
                    outline: 'none',
                    '&:focus-visible': { boxShadow: `inset 0 0 0 2px ${col.current}` },
                }}
            >
                <UnfoldMoreIcon sx={{ fontSize: 16 }} />
                <span>{s.to - s.from} unchanged line{s.to - s.from === 1 ? '' : 's'}</span>
                {path.length > 0 && (
                    <Box component="span" sx={{ ml: 'auto', display: 'flex', alignItems: 'center', minWidth: 0, opacity: 0.85, fontWeight: 600 }}>
                        {path.map((t, i) => (
                            <React.Fragment key={i}>
                                {i > 0 && <ChevronRightIcon sx={{ fontSize: 14, opacity: 0.6 }} />}
                                <Box component="span" sx={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 260 }}>{t}</Box>
                            </React.Fragment>
                        ))}
                    </Box>
                )}
            </Box>
        );
    };

    const textCell = {
        whiteSpace: wrap ? 'pre-wrap' : 'pre',
        overflowWrap: wrap ? 'anywhere' : 'normal',
        overflow: wrap ? 'visible' : 'hidden',
        textOverflow: wrap ? 'clip' : 'ellipsis',
        minWidth: 0,
        pl: 1,
        pr: 1.5,
    } as const;
    const numCell = {
        textAlign: 'right', pr: 1, pl: 0.5, color: p.gutter, userSelect: 'none', fontSize: 11.5,
    } as const;
    const signCell = { textAlign: 'center', userSelect: 'none', fontWeight: 700 } as const;
    const currentChunk = current >= 0 ? changeChunks[current] : -1;

    // Side by side: old | gutter | new, with the empty half of an added or
    // removed line hatched rather than blank, so a gap is visibly a gap.
    const renderSplit = () => {
        const hatch = `repeating-linear-gradient(135deg, transparent 0 5px, ${col.filler} 5px 6px)`;
        const items: React.ReactNode[] = [];
        let lastChunk = -1;
        shown.slice(0, limit).forEach(s => {
            if ('fold' in s) { items.push(foldBand(s, '1 / -1')); return; }
            const r = s.row as Row;
            const firstOfChunk = r.kind !== 'equal' && r.chunk !== lastChunk;
            lastChunk = r.kind !== 'equal' ? r.chunk : -1;
            const isCur = r.chunk === currentChunk && r.kind !== 'equal';
            let wa: Span[] | null = null, wb: Span[] | null = null;
            if (r.kind === 'mod' && r.a !== null && r.b !== null) {
                const w = wordDiff(a[r.a], b[r.b]);
                wa = w.a; wb = w.b;
            }
            const aBg = r.kind === 'del' || r.kind === 'mod' ? col.delLine : undefined;
            const bBg = r.kind === 'ins' || r.kind === 'mod' ? col.addLine : undefined;
            const aFill = r.a === null ? hatch : undefined;
            const bFill = r.b === null ? hatch : undefined;
            const accent = isCur ? `inset 3px 0 0 ${col.current}` : undefined;
            const mid = r.kind === 'equal' ? 'transparent'
                : r.kind === 'mod' ? `linear-gradient(90deg, ${col.delGutter}, ${col.addGutter})`
                : r.kind === 'del' ? col.delGutter : col.addGutter;
            items.push(
                <React.Fragment key={`r${s.index}`}>
                    <Box data-row={s.index} data-chunk={firstOfChunk ? r.chunk : undefined}
                        sx={{ ...numCell, bgcolor: aBg ?? p.gutterBg, backgroundImage: aFill, boxShadow: accent }}>
                        {r.a !== null ? r.a + 1 : ''}
                    </Box>
                    <Box sx={{ ...signCell, bgcolor: aBg, backgroundImage: aFill, color: col.delInk }}>
                        {r.kind === 'del' || r.kind === 'mod' ? '−' : ''}
                    </Box>
                    <Box sx={{ ...textCell, bgcolor: aBg, backgroundImage: aFill }}>
                        {r.a !== null && (
                            <Painted line={a[r.a]} state={aStates[r.a]} st={st} spans={wa} tint={col.delWord} p={p} />
                        )}
                    </Box>
                    <Box sx={{ background: mid, borderLeft: `1px solid ${alpha(p.gutter, 0.25)}`, borderRight: `1px solid ${alpha(p.gutter, 0.25)}` }} />
                    <Box sx={{ ...numCell, bgcolor: bBg ?? p.gutterBg, backgroundImage: bFill }}>
                        {r.b !== null ? r.b + 1 : ''}
                    </Box>
                    <Box sx={{ ...signCell, bgcolor: bBg, backgroundImage: bFill, color: col.addInk }}>
                        {r.kind === 'ins' || r.kind === 'mod' ? '+' : ''}
                    </Box>
                    <Box sx={{ ...textCell, bgcolor: bBg, backgroundImage: bFill }}>
                        {r.b !== null && (
                            <Painted line={b[r.b]} state={bStates[r.b]} st={st} spans={wb} tint={col.addWord} p={p} />
                        )}
                    </Box>
                </React.Fragment>,
            );
        });
        return (
            <Box sx={{
                display: 'grid',
                gridTemplateColumns: `${gutterCh + 1}ch 2ch minmax(0, 1fr) 6px ${gutterCh + 1}ch 2ch minmax(0, 1fr)`,
                alignItems: 'stretch',
            }}>
                {items}
            </Box>
        );
    };

    // Unified: one column, old line numbers and new, removals before
    // additions as a patch reads.
    const renderUnified = () => {
        const items: React.ReactNode[] = [];
        let lastChunk = -1;
        shown.slice(0, limit).forEach(s => {
            if ('fold' in s) { items.push(foldBand(s, '1 / -1')); return; }
            const r = s.row as UniRow;
            const firstOfChunk = r.kind !== 'equal' && r.chunk !== lastChunk;
            lastChunk = r.kind !== 'equal' ? r.chunk : -1;
            const isCur = r.chunk === currentChunk && r.kind !== 'equal';
            let spans: Span[] | null = null;
            if (r.other !== null) {
                const w = r.kind === 'del' ? wordDiff(a[r.a as number], b[r.other]) : wordDiff(a[r.other], b[r.b as number]);
                spans = r.kind === 'del' ? w.a : w.b;
            }
            const bg = r.kind === 'del' ? col.delLine : r.kind === 'ins' ? col.addLine : undefined;
            const line = r.kind === 'del' ? a[r.a as number] : b[r.b as number];
            const state = r.kind === 'del' ? aStates[r.a as number] : bStates[r.b as number];
            items.push(
                <React.Fragment key={`u${s.index}`}>
                    <Box data-row={s.index} data-chunk={firstOfChunk ? r.chunk : undefined}
                        sx={{ ...numCell, bgcolor: bg ?? p.gutterBg, boxShadow: isCur ? `inset 3px 0 0 ${col.current}` : undefined }}>
                        {r.a !== null ? r.a + 1 : ''}
                    </Box>
                    <Box sx={{ ...numCell, bgcolor: bg ?? p.gutterBg }}>{r.b !== null ? r.b + 1 : ''}</Box>
                    <Box sx={{ ...signCell, bgcolor: bg, color: r.kind === 'del' ? col.delInk : col.addInk }}>
                        {r.kind === 'del' ? '−' : r.kind === 'ins' ? '+' : ''}
                    </Box>
                    <Box sx={{ ...textCell, bgcolor: bg }}>
                        <Painted line={line} state={state} st={st} spans={spans}
                            tint={r.kind === 'del' ? col.delWord : col.addWord} p={p} />
                    </Box>
                </React.Fragment>,
            );
        });
        return (
            <Box sx={{
                display: 'grid',
                gridTemplateColumns: `${gutterCh + 1}ch ${gutterCh + 1}ch 2ch minmax(0, 1fr)`,
            }}>
                {items}
            </Box>
        );
    };

    // Where the changes are in the whole comparison, down the right edge:
    // Beyond Compare's thumbnail, and a way to jump.
    const ruler = () => {
        const total = Math.max(1, list.length);
        return (
            <Box sx={{ position: 'relative', width: 14, flex: '0 0 auto', bgcolor: alpha(p.gutter, 0.08), borderLeft: `1px solid ${alpha(p.gutter, 0.2)}` }}>
                {changeChunks.map((ci, k) => {
                    const first = list.findIndex(r => r.chunk === ci && r.kind !== 'equal');
                    if (first < 0) return null;
                    let last = first;
                    while (last + 1 < list.length && list[last + 1].chunk === ci) last++;
                    const c = chunks[ci];
                    const color = c.aLen === 0 ? col.addInk : c.bLen === 0 ? col.delInk : col.modInk;
                    return (
                        <Tooltip key={ci} size="sm" placement="left"
                            title={`${c.bLen ? `+${c.bLen}` : ''}${c.aLen && c.bLen ? ' ' : ''}${c.aLen ? `−${c.aLen}` : ''}`}>
                            <Box
                                onClick={() => goTo(k)}
                                sx={{
                                    position: 'absolute', left: 2, right: 2,
                                    top: `${(first / total) * 100}%`,
                                    height: `max(3px, ${((last - first + 1) / total) * 100}%)`,
                                    bgcolor: color, borderRadius: 1, cursor: 'pointer',
                                    opacity: k === current ? 1 : 0.75,
                                    boxShadow: k === current ? `0 0 0 1.5px ${col.current}` : undefined,
                                }}
                            />
                        </Tooltip>
                    );
                })}
            </Box>
        );
    };

    const paneHead = (side: DiffSide, which: 'a' | 'b') => (
        <Box sx={{
            display: 'flex', alignItems: 'center', gap: 1, minWidth: 0, px: 1.25, py: 0.75,
            borderBottom: `2px solid ${which === 'a' ? col.delInk : col.addInk}`,
        }}>
            <Box sx={{
                flex: '0 0 auto', width: 20, height: 20, borderRadius: '50%', display: 'grid', placeItems: 'center',
                fontSize: 11, fontWeight: 800, color: '#fff', bgcolor: which === 'a' ? col.delInk : col.addInk,
            }}>{which === 'a' ? 'A' : 'B'}</Box>
            <Typography level="title-sm" sx={{ fontFamily: MONO, whiteSpace: 'nowrap' }}>{side.label}</Typography>
            {side.detail && (
                <Typography level="body-xs" sx={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', color: 'text.tertiary' }}>
                    {side.detail}
                </Typography>
            )}
            {side.missing && <Chip size="sm" variant="soft" color="neutral">did not exist</Chip>}
        </Box>
    );

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: 0, flex: 1, gap: 1 }}>
            {!placeholder && <DiffSummary stats={stats} outline={outline} identical={identical} loading={loading} />}

            {/* The toolbar. */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                <ToggleButtonGroup size="sm" value={shownView} onChange={(_e, v) => v && setView(v as any)}>
                    {!isMobile && <Button value="split" startDecorator={<ViewColumnOutlinedIcon />}>Side by side</Button>}
                    <Button value="unified" startDecorator={<ViewStreamOutlinedIcon />}>Unified</Button>
                    <Button value="outline" startDecorator={<AccountTreeOutlinedIcon />}>Outline</Button>
                </ToggleButtonGroup>
                {shownView !== 'outline' && (
                    <>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.25 }}>
                            <Tooltip size="sm" title="Previous change (p or k)">
                                <span><IconButton size="sm" variant="outlined" disabled={changeChunks.length === 0} onClick={() => goTo(current - 1)}>
                                    <KeyboardArrowUpIcon />
                                </IconButton></span>
                            </Tooltip>
                            <Tooltip size="sm" title="Next change (n or j)">
                                <span><IconButton size="sm" variant="outlined" disabled={changeChunks.length === 0} onClick={() => goTo(current + 1)}>
                                    <KeyboardArrowDownIcon />
                                </IconButton></span>
                            </Tooltip>
                            <Typography level="body-xs" sx={{ ml: 0.5, minWidth: 64, color: 'text.tertiary' }}>
                                {changeChunks.length === 0 ? 'no changes'
                                    : current < 0 ? `${changeChunks.length} change${changeChunks.length === 1 ? '' : 's'}`
                                    : `${current + 1} of ${changeChunks.length}`}
                            </Typography>
                        </Box>
                        <Select size="sm" value={context} onChange={(_e, v) => v !== null && setContext(v as number)}
                            sx={{ minWidth: 150 }} renderValue={o => <span>{o?.label}</span>}>
                            <Option value={0} label="Changes only">Changes only</Option>
                            <Option value={3} label="3 lines of context">3 lines of context</Option>
                            <Option value={10} label="10 lines of context">10 lines of context</Option>
                            <Option value={-1} label="Whole file">Whole file</Option>
                        </Select>
                        <Tooltip size="sm" title={wrap ? 'Stop wrapping long lines' : 'Wrap long lines'}>
                            <IconButton size="sm" variant={wrap ? 'solid' : 'outlined'} color="neutral" onClick={() => setWrap(!wrap)}>
                                <WrapTextIcon />
                            </IconButton>
                        </Tooltip>
                    </>
                )}
                <Tooltip size="sm" title={ignoreWs ? 'Whitespace is ignored: re-indenting a drawer or realigning a table is no change' : 'Ignore changes in whitespace'}>
                    <IconButton size="sm" variant={ignoreWs ? 'solid' : 'outlined'} color="neutral" onClick={() => setIgnoreWs(!ignoreWs)}>
                        <SpaceBarIcon />
                    </IconButton>
                </Tooltip>
                <Box sx={{ ml: 'auto' }} />
                <Tooltip size="sm" title="Copy the changes as a patch (unified diff)">
                    <span><Button size="sm" variant="outlined" color="neutral" disabled={identical}
                        startDecorator={<ContentCopyIcon />} onClick={copyPatch}>
                        {copied ? 'Copied' : 'Patch'}
                    </Button></span>
                </Tooltip>
            </Box>

            {/* The comparison. */}
            <Box sx={{
                flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column',
                border: '1px solid', borderColor: 'divider', borderRadius: 'md', overflow: 'hidden',
                bgcolor: p.bg, color: p.fg,
            }}>
                {shownView === 'split' && (
                    <Box sx={{ display: 'grid', gridTemplateColumns: 'minmax(0,1fr) 6px minmax(0,1fr)', pr: '14px', bgcolor: p.gutterBg }}>
                        {paneHead(left, 'a')}<Box />{paneHead(right, 'b')}
                    </Box>
                )}
                {shownView === 'unified' && (
                    <Box sx={{ display: 'flex', bgcolor: p.gutterBg, '& > *': { flex: 1, minWidth: 0 } }}>
                        {paneHead(left, 'a')}{paneHead(right, 'b')}
                    </Box>
                )}
                {placeholder ? (
                    <Box sx={{ flex: 1, display: 'grid', placeItems: 'center', p: 3, color: p.gutter }}>{placeholder}</Box>
                ) : shownView === 'outline' ? (
                    <Box sx={{ flex: 1, minHeight: 0, overflow: 'auto' }}>
                        <DiffOutline outline={outline} st={st} p={p} dark={dark} onJump={jumpToLine} identical={identical && !nothing} />
                    </Box>
                ) : (
                    <Box sx={{ flex: 1, minHeight: 0, display: 'flex' }}>
                        <Box
                            ref={scroller}
                            onScroll={onScroll}
                            sx={{
                                flex: 1, minWidth: 0, overflow: 'auto',
                                fontFamily: MONO, fontSize: 12.5, lineHeight: 1.6,
                                '& ::selection': { backgroundColor: p.selBg },
                            }}
                        >
                            {identical && !nothing ? (
                                <Box sx={{ p: 4, textAlign: 'center', fontFamily: 'var(--joy-fontFamily-body)', color: p.gutter }}>
                                    {ignoreWs ? 'No differences, ignoring whitespace.' : 'The two sides are identical.'}
                                </Box>
                            ) : shownView === 'split' ? renderSplit() : renderUnified()}
                            {limit < shown.length && (
                                <Box sx={{ p: 1, color: p.gutter, fontSize: 12 }}>… {shown.length - limit} more rows</Box>
                            )}
                        </Box>
                        {!identical && ruler()}
                    </Box>
                )}
            </Box>
        </Box>
    );
}
