// The editor's help: its keys and expansions, from docs/editor.org in the
// orgs repo. The server embeds that file at build time and renders it (GET
// /editor/help), so the help is one org document rather than a second copy
// kept here, and it is asked for each time it is opened rather than bundled.
//
// Anything can open it - F1 or SPC ? in the editor, the Keys button under it,
// the settings menu - through openEditorHelp(), which is a window event
// because the settings menu and the editor sit in different branches of the
// tree. App mounts the one dialog that listens.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Typography from '@mui/joy/Typography';
import CircularProgress from '@mui/joy/CircularProgress';
import { ODb } from '../db';

const EVENT = 'worg-editor-help';

export function openEditorHelp() {
    window.dispatchEvent(new Event(EVENT));
}

export default function EditorHelp() {
    const [open, setOpen] = React.useState(false);
    const [html, setHtml] = React.useState('');
    const [error, setError] = React.useState('');

    React.useEffect(() => {
        const on = () => {
            setOpen(true);
            setError('');
            ODb.editorHelp()
                .then(r => { if (r && r.Ok) setHtml(r.Html); else setError((r && r.Msg) || 'The server has no editor help.'); })
                .catch(e => setError(String((e && e.message) || e)));
        };
        window.addEventListener(EVENT, on);
        return () => window.removeEventListener(EVENT, on);
    }, []);

    return (
        <Modal open={open} onClose={() => setOpen(false)}>
            <ModalDialog layout="center" sx={{ width: 'min(900px, 94vw)', maxHeight: '88vh', overflow: 'auto', p: 3 }}>
                <ModalClose />
                {html === '' && error === '' && <CircularProgress size="sm" />}
                {error !== '' && <Typography color="danger">{error}</Typography>}
                <Box
                    dangerouslySetInnerHTML={{ __html: html }}
                    sx={{
                        fontSize: 14,
                        lineHeight: 1.5,
                        color: 'text.primary',
                        '& h1, & h2, & h3': { fontWeight: 700, lineHeight: 1.25 },
                        '& h1': { fontSize: 22, mt: 0 },
                        '& h2': { fontSize: 18, mt: 3, mb: 1, pb: 0.5, borderBottom: '1px solid', borderColor: 'divider' },
                        '& h3': { fontSize: 15, mt: 2, mb: 0.5 },
                        '& table': { borderCollapse: 'collapse', width: '100%', my: 1, fontSize: 13 },
                        '& th, & td': { textAlign: 'left', verticalAlign: 'top', p: '4px 10px', borderBottom: '1px solid', borderColor: 'divider' },
                        '& th': { bgcolor: 'background.level1', fontWeight: 600 },
                        '& code, & kbd': {
                            fontFamily: '"SFMono-Regular", "JetBrains Mono", Consolas, Menlo, monospace',
                            fontSize: 12.5, bgcolor: 'background.level1', borderRadius: '4px', px: 0.5, whiteSpace: 'nowrap',
                        },
                        '& pre': { bgcolor: 'background.level1', p: 1.5, borderRadius: 'sm', overflow: 'auto', fontSize: 12.5 },
                        '& ul': { pl: 3 },
                        '& p': { my: 1 },
                    }}
                />
            </ModalDialog>
        </Modal>
    );
}
