// Worg run inside another application's page - the VS Code plugin's webview.
//
// The plugin opens worg in an iframe with `?embed=vscode&app=Agenda`. Being
// framed changes three things:
//
// - **The token comes from the host.** worg's own login lives in a SameSite
//   cookie, and inside a frame on another site that cookie is neither sent nor
//   reliably kept. The plugin already holds a token and refreshes it, so it
//   posts it in (`worg:token`) and keeps posting it as it changes. It does not
//   go on the url, where it would land in logs and history.
// - **Opening a heading means the host's editor.** A reader in VS Code wants
//   the file in VS Code, not in worg's own editor, so a jump to a file is
//   posted out (`worg:open`) instead of switching to the Files tab.
// - **The colour scheme is the host's** (`worg:theme`).
//
// Out of a frame none of this is live: `isEmbedded()` is false, `postToHost`
// does nothing, and the listener ignores everything.

const params = typeof window !== 'undefined'
    ? new URLSearchParams(window.location.search)
    : new URLSearchParams();

const framed = (() => {
    try {
        return typeof window !== 'undefined' && window.parent !== window;
    } catch {
        return true;
    }
})();

// Who is hosting worg, or '' when nobody is. Asked for by the url rather than
// guessed from being framed, so worg framed by something that never asked for
// any of this behaves as it always did.
export const embedHost: string = framed ? (params.get('embed') || '') : '';

export function isEmbedded(): boolean {
    return embedHost !== '';
}

// The application the url asked to open on, if any. Checked against the names
// App switches on by the caller.
export function initialApp(): string | null {
    return params.get('app');
}

// The colour scheme the url asked for, so the first paint is already right
// rather than flashing the other one before the host's message arrives.
export function initialTheme(): 'light' | 'dark' | null {
    const t = params.get('theme');
    return t === 'light' || t === 'dark' ? t : null;
}

export type HostOpen = {
    type: 'worg:open';
    filename: string;
    // 0-based, as worg's FileJump has it.
    line?: number;
    heading?: string;
    hash?: string;
};

export type HostMessage =
    | { type: 'worg:ready' }
    | { type: 'worg:app'; app: string; title: string }
    | HostOpen;

export function postToHost(msg: HostMessage) {
    if (!isEmbedded()) return;
    // '*' because the host's origin is the webview's own and not knowable from
    // here. Nothing posted out is a secret: file names, lines and headings.
    window.parent.postMessage(msg, '*');
}

// The origin of the page hosting worg, when it is a VS Code webview - and only
// then. `ancestorOrigins` is Chromium's, which is what VS Code is.
function webviewOrigin(): string | null {
    if (!isEmbedded()) return null;
    try {
        const anc = window.location.ancestorOrigins;
        const o = anc && anc.length > 0 ? anc[0] : '';
        return o.startsWith('vscode-webview://') ? o : null;
    } catch {
        return null;
    }
}

// A login made in worg's own form, handed to the host so it outlives this
// panel: the host keeps it, refreshes it, and hands it to the next panel
// opened. Sent only to a VS Code webview by its exact origin - a token posted
// to '*' would go to any site that framed worg with ?embed= and waited for a
// login.
export function postTokenToHost(token: string | null, expiresAt?: number) {
    const origin = webviewOrigin();
    if (!origin) return;
    window.parent.postMessage({ type: 'worg:login', token, expiresAt }, origin);
}

export type FromHost =
    | { type: 'worg:token'; token: string | null; expiresAt?: number }
    | { type: 'worg:theme'; mode: 'light' | 'dark' }
    | { type: 'worg:app'; app: string };

// Messages from the host, and only from the host: anything posted by some
// other frame - a rendered org file in an iframe of our own, say - is dropped.
export function onHostMessage(fn: (msg: FromHost) => void): () => void {
    if (!isEmbedded()) return () => { };
    const listener = (e: MessageEvent) => {
        if (e.source !== window.parent) return;
        const d = e.data;
        if (!d || typeof d.type !== 'string' || !d.type.startsWith('worg:')) return;
        fn(d as FromHost);
    };
    window.addEventListener('message', listener);
    return () => window.removeEventListener('message', listener);
}
