// React's side of the force layout: the animation frame, the dragging, and the
// box the picture is drawn in.
//
// The positions live in a **ref** and the component is nudged to repaint once
// per frame. That is deliberate: state would put React between the simulation
// and the numbers it is changing sixty times a second, and the simulation would
// spend its time reconciling rather than settling.

import * as React from 'react';
import {
    FNode, FEdge, Pt, seedPositions, stepForces, COOLING, SETTLED,
} from './forcelayout';

export type ForceLayout = {
    // Hang this on the box the picture is drawn in, so the layout knows how big
    // it is. A **callback** ref rather than an object one, and that is not a
    // style choice: both graphs return a different element while they have
    // nothing to draw, so the element the observer should be watching changes
    // the moment the data arrives. An effect that read `ref.current` once at
    // mount went on measuring the detached empty-state box for ever, and the
    // graph stayed at its initial 520x260 in the corner of a panel ten times
    // that size.
    wrapRef: (el: HTMLDivElement | null) => void;
    size: { w: number; h: number };
    // Where everything currently is. Read during render; do not write to it.
    pos: Map<string, Pt>;
    // Whether a node is being dragged, for the cursor.
    dragging: boolean;
    // Hand these to the svg and to each node respectively.
    svgHandlers: {
        onPointerMove: (e: React.PointerEvent) => void;
        onPointerUp: () => void;
        onPointerLeave: () => void;
    };
    onNodePointerDown: (e: React.PointerEvent, id: string) => void;
    // True when the pointer went down and came up without moving, which is the
    // only time a click on a node should count as picking it.
    wasDrag: () => boolean;
};

export function useForceLayout(
    nodes: FNode[],
    edges: FEdge[],
    height: number,
    distanceOf?: (n: FNode) => number,
): ForceLayout {
    const [size, setSize] = React.useState({ w: 520, h: height });
    const elRef = React.useRef<HTMLDivElement | null>(null);
    const roRef = React.useRef<ResizeObserver | null>(null);
    const posRef = React.useRef<Map<string, Pt>>(new Map());
    // Bumped to repaint after a step. The value itself is never read.
    const [, setTick] = React.useState(0);
    const dragRef = React.useRef<{ id: string; dx: number; dy: number; moved: boolean } | null>(null);
    const [dragging, setDragging] = React.useState(false);
    const frameRef = React.useRef<number | null>(null);
    const alphaRef = React.useRef(1);
    const stepRef = React.useRef<() => void>(() => {});
    const movedRef = React.useRef(false);

    // `height` is the floor, not the size: the file view gives its graph a fixed
    // height and the links tab lets it fill whatever is left of the panel. A box
    // measured at nothing while the page is still laying out would otherwise pin
    // every node into a line along the top.
    const measure = React.useCallback((el: HTMLDivElement) => {
        const w = Math.max(240, Math.round(el.clientWidth));
        const h = Math.max(height, Math.round(el.clientHeight));
        setSize(s => (s.w === w && s.h === h ? s : { w, h }));
    }, [height]);

    const wrapRef = React.useCallback((el: HTMLDivElement | null) => {
        if (roRef.current) {
            roRef.current.disconnect();
            roRef.current = null;
        }
        elRef.current = el;
        if (!el) return;
        const ro = new ResizeObserver(() => measure(el));
        ro.observe(el);
        roRef.current = ro;
        measure(el);
    }, [measure]);

    // A height change has to be taken even when the element did not move.
    React.useEffect(() => {
        if (elRef.current) measure(elRef.current);
    }, [measure]);

    React.useEffect(() => () => {
        if (roRef.current) roRef.current.disconnect();
    }, []);

    React.useEffect(() => {
        if (nodes.length === 0) {
            posRef.current = new Map();
            setTick(t => t + 1);
            return;
        }
        const old = posRef.current;
        const next = seedPositions(nodes, size.w, size.h, distanceOf);
        // Keep a node where it already was, so changing an option - a depth, a
        // filter - does not throw the whole picture in the air.
        next.forEach((p, id) => {
            const prev = old.get(id);
            if (prev) {
                p.x = prev.x;
                p.y = prev.y;
            }
        });
        posRef.current = next;
        alphaRef.current = 1;

        const step = () => {
            stepForces(nodes, edges, posRef.current, size.w, size.h, alphaRef.current);
            alphaRef.current *= COOLING;
            setTick(t => t + 1);
            if (alphaRef.current > SETTLED || dragRef.current !== null) {
                frameRef.current = requestAnimationFrame(step);
            } else {
                frameRef.current = null;
            }
        };
        stepRef.current = step;
        frameRef.current = requestAnimationFrame(step);
        return () => {
            if (frameRef.current !== null) cancelAnimationFrame(frameRef.current);
            frameRef.current = null;
        };
    }, [nodes, edges, size.w, size.h, distanceOf]);

    // Put some energy back in and make sure a frame is pending.
    //
    // The loop is restarted from here rather than from an effect, and that is
    // load-bearing: an effect that reschedules itself off its own state update
    // never stops, because nothing decays alpha unless a step actually runs.
    const kick = React.useCallback((a: number) => {
        alphaRef.current = Math.max(alphaRef.current, a);
        if (frameRef.current === null) {
            frameRef.current = requestAnimationFrame(() => stepRef.current());
        }
    }, []);

    const onNodePointerDown = React.useCallback((e: React.PointerEvent, id: string) => {
        const p = posRef.current.get(id);
        const svg = (e.currentTarget as SVGElement).ownerSVGElement;
        if (!p || !svg) return;
        const box = svg.getBoundingClientRect();
        dragRef.current = { id, dx: p.x - (e.clientX - box.left), dy: p.y - (e.clientY - box.top), moved: false };
        movedRef.current = false;
        p.fixed = true;
        setDragging(true);
        (e.target as Element).setPointerCapture?.(e.pointerId);
        kick(0.35);
    }, [kick]);

    const onPointerMove = React.useCallback((e: React.PointerEvent) => {
        const drag = dragRef.current;
        if (!drag) return;
        const box = (e.currentTarget as SVGSVGElement).getBoundingClientRect();
        const p = posRef.current.get(drag.id);
        if (!p) return;
        const nx = e.clientX - box.left + drag.dx;
        const ny = e.clientY - box.top + drag.dy;
        if (Math.abs(nx - p.x) > 1 || Math.abs(ny - p.y) > 1) {
            drag.moved = true;
            movedRef.current = true;
        }
        p.x = nx;
        p.y = ny;
        setTick(t => t + 1);
    }, []);

    const endDrag = React.useCallback(() => {
        const drag = dragRef.current;
        if (!drag) return;
        const p = posRef.current.get(drag.id);
        if (p) p.fixed = false;
        dragRef.current = null;
        setDragging(false);
        kick(0.25);
    }, [kick]);

    return {
        wrapRef,
        size,
        pos: posRef.current,
        dragging,
        svgHandlers: { onPointerMove, onPointerUp: endDrag, onPointerLeave: endDrag },
        onNodePointerDown,
        // A drag that moved is not a click. Without this, letting go of a node
        // you have just dragged across the canvas opens whatever it points at.
        wasDrag: () => movedRef.current,
    };
}
