import * as React from 'react';
import GlobalStyles from '@mui/joy/GlobalStyles';
import Sheet from '@mui/joy/Sheet';
import Box from '@mui/joy/Box';
import Typography from '@mui/joy/Typography';
import IconButton from '@mui/joy/IconButton';
import MenuIcon from '@mui/icons-material/Menu';
import AddIcon from '@mui/icons-material/Add';

import ColorSchemeToggle from './ColorSchemeToggle';
import SettingsMenu from './SettingsMenu';
import { toggleSidebar } from '../utils';
import { useIsMobile } from '../useMobile';

// The fixed bar across the top of a narrow screen: the way to the nav, which
// panel you are on, and the two things that are about the app rather than about
// the page.
//
// The title is here because the big one in the page is not drawn on a phone -
// see App.tsx. Without it a phone has nothing on screen saying which panel it is
// looking at, which matters far more when only one panel fits than it does on a
// desktop where the nav is showing the selected entry all the time.
//
// It follows `useIsMobile` rather than a raw `md` breakpoint, and that is not a
// detail. App.tsx drops the big page title whenever `isMobile`, so if this bar
// appeared on a different signal there would be a band of widths - a tablet in
// landscape, or anyone who picked the phone layout by hand - where the title had
// been taken away and nothing had been put in its place. Whatever removes the
// title has to be what puts this here.
//
// Above it, the function bar is in the flow and carries the nav button itself;
// below it the rail is off-canvas and the hamburger here is the only way to the
// drawer. On a wide screen in forced phone layout both are showing, which is one
// button more than is needed and not a problem.
export default function Header({ title, onCapture }: { title?: string; onCapture?: () => void } = {}) {
  const isMobile = useIsMobile();
  return (
    <Sheet
      sx={{
        display: isMobile ? 'flex' : 'none',
        alignItems: 'center',
        gap: 1,
        position: 'fixed',
        top: 0,
        width: '100vw',
        height: 'var(--Header-height)',
        zIndex: 9995,
        // Narrower than the page's own gutter used to be: this row holds three
        // controls and a title, and the title is the one that needs the room.
        px: 1.5,
        borderBottom: '1px solid',
        borderColor: 'background.level1',
        boxShadow: 'sm',
      }}
    >
      {/* The height the main content pads itself by. Driven by the same flag
          as the bar above rather than by a breakpoint of its own - a bar that is
          showing with a height of zero behind it lies over the first row of
          whatever panel is open. */}
      <GlobalStyles
        styles={{ ':root': { '--Header-height': isMobile ? '52px' : '0px' } }}
      />
      <IconButton
        onClick={() => toggleSidebar()}
        variant="outlined"
        color="neutral"
        // `md` rather than `sm`: this is the one control on the page that has to
        // be hit first time, and a 32px target under a thumb is not one. 40px is
        // the smallest that reliably is.
        size="md"
        aria-label="Applications"
      >
        <MenuIcon />
      </IconButton>
      {title && (
        <Typography
          level="title-md"
          // One line, ellipsised. "Clock Report" fits; a long panel name on a
          // 320px screen would otherwise push the settings buttons off the edge.
          sx={{
            flex: 1,
            minWidth: 0,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
          }}
        >
          {title}
        </Typography>
      )}
      <Box sx={{ display: 'flex', gap: 0.5, ml: title ? 0 : 'auto' }}>
        {/* Capture, in the bar rather than only in the drawer: on a phone it
            is the thing reached for most, and the rail it lives on at a desk
            is off the screen until the drawer is opened. */}
        {onCapture && (
          <IconButton size="md" variant="solid" color="primary" aria-label="Capture" onClick={onCapture}>
            <AddIcon />
          </IconButton>
        )}
        <ColorSchemeToggle id={undefined} size="md" />
        <SettingsMenu size="md" />
      </Box>
    </Sheet>
  );
}
