// Adding a task to the chart in one line.
//
//   Write the spec 3d @Sam #design ^fri >kickoff !A RISK=high
//
// is a TODO called "Write the spec", three days of effort, ASSIGNED (or
// whichever property says who) to Sam, tagged :design:, scheduled on Friday,
// waiting on the task called something like "kickoff", priority A, with a RISK
// property. Anything not recognised is the title.
//
// The other half is the chart's query. A task the query does not find is
// written and then vanishes, which looks exactly like the add failing - so the
// line is filled out with whatever the query insists on (`queryNeeds`): its
// tags, its keyword, the properties it tests for. What it cannot be sure of is
// said rather than guessed (`QuickPlan.warnings`), and the page checks after
// the write whether the new task really is on the chart.
//
// Pure and tested (ganttquick.test.ts): parsing a sentence for its bits is
// exactly the sort of code that is wrong about the one word nobody tried.

import { GanttTask, dayKey, startOfDay } from './gantt';
import { propOf, personOf } from './ganttplan';

// --- what a query insists on ------------------------------------------------

export interface QueryNeeds {
    // A todo keyword of some kind (IsTodo, IsTask, IsActive...).
    todo: boolean;
    // A keyword in particular (IsStatus).
    status: string;
    tags: string[];
    // Tags it rules out (!HasTags).
    notTags: string[];
    // Properties it tests: a name, and when the test is a regular expression
    // the expression, so a value can be chosen that passes it.
    props: { name: string; re: string }[];
    priority: string;
    // A pattern the headline has to match.
    headline: string;
    // Things the query asks that a new line cannot be made to satisfy here,
    // in words.
    notes: string[];
}

// Split at a separator outside quotes and brackets.
function splitTop(s: string, sep: string): string[] {
    const out: string[] = [];
    let depth = 0;
    let quote = '';
    let cur = '';
    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (quote) {
            cur += c;
            if (c === '\\' && i + 1 < s.length) { cur += s[++i]; continue; }
            if (c === quote) quote = '';
            continue;
        }
        if (c === '"' || c === "'" || c === '`') { quote = c; cur += c; continue; }
        if (c === '(') depth++;
        if (c === ')') depth--;
        if (depth === 0 && s.startsWith(sep, i)) {
            out.push(cur);
            cur = '';
            i += sep.length - 1;
            continue;
        }
        cur += c;
    }
    out.push(cur);
    return out.map(x => x.trim()).filter(x => x !== '');
}

// Whether brackets at either end of an expression wrap the whole of it.
function unwrap(s: string): string {
    let t = s.trim();
    for (;;) {
        if (!t.startsWith('(') || !t.endsWith(')')) return t;
        let depth = 0;
        let quote = '';
        let whole = true;
        for (let i = 0; i < t.length; i++) {
            const c = t[i];
            if (quote) { if (c === '\\') i++; else if (c === quote) quote = ''; continue; }
            if (c === '"' || c === "'" || c === '`') { quote = c; continue; }
            if (c === '(') depth++;
            if (c === ')') { depth--; if (depth === 0 && i < t.length - 1) { whole = false; break; } }
        }
        if (!whole) return t;
        t = t.slice(1, -1).trim();
    }
}

function unquote(s: string): string {
    const t = s.trim();
    if (t.length >= 2 && (t[0] === '"' || t[0] === "'" || t[0] === '`') && t[t.length - 1] === t[0]) {
        return t.slice(1, -1).replace(/\\(.)/g, '$1');
    }
    return t;
}

// The plain text a regular expression matches, when it matches only one:
// "^design$" and "design" are "design"; "des.*" is not plain.
export function literalOf(re: string): string | null {
    const t = re.replace(/^\^/, '').replace(/\$$/, '');
    if (t === '' || /[.*+?()[\]{}|\\]/.test(t)) return null;
    return t;
}

const TODO_CALLS = new Set(['IsTodo', 'IsTask', 'IsActive', 'HasAStatus', 'IsNextTask']);

export function queryNeeds(query: string): QueryNeeds {
    const needs: QueryNeeds = {
        todo: false, status: '', tags: [], notTags: [], props: [], priority: '', headline: '', notes: [],
    };
    const visit = (expr: string, negated: boolean) => {
        let e = unwrap(expr);
        // Either side of an "or" is enough, so the first is the one aimed for.
        const alts = splitTop(e, '||');
        if (alts.length > 1) {
            if (negated) return;
            e = unwrap(alts[0]);
        }
        const parts = splitTop(e, '&&');
        if (parts.length > 1) {
            if (!negated) parts.forEach(p => visit(p, false));
            return;
        }
        let one = unwrap(parts[0] || '');
        let neg = negated;
        while (one.startsWith('!')) { neg = !neg; one = unwrap(one.slice(1)); }
        if (one !== unwrap(parts[0] || '')) { visit(one, neg); return; }
        const m = one.match(/^([A-Za-z_]\w*)\s*\(([\s\S]*)\)$/);
        if (!m) {
            if (/\{\{.*\}\}/.test(one)) needs.notes.push(`uses the filter ${one.trim()}`);
            return;
        }
        const fn = m[1];
        const args = splitTop(m[2], ',').map(unquote);
        if (neg) {
            if (fn === 'HasTags') needs.notTags.push(...args);
            return;
        }
        if (TODO_CALLS.has(fn)) needs.todo = true;
        else if (fn === 'IsStatus' && args[0]) needs.status = args[0];
        else if (fn === 'HasTags') args.forEach(a => { if (a && needs.tags.indexOf(a) < 0) needs.tags.push(a); });
        else if (fn === 'HasTagMatching' && args[0]) {
            const lit = literalOf(args[0]);
            if (lit) { if (needs.tags.indexOf(lit) < 0) needs.tags.push(lit); }
            else needs.notes.push(`needs a tag matching /${args[0]}/`);
        }
        else if (fn === 'HasProperty' && args[0]) needs.props.push({ name: args[0].toUpperCase(), re: '' });
        else if (fn === 'MatchProperty' && args[0]) needs.props.push({ name: args[0].toUpperCase(), re: args[1] || '' });
        else if (fn === 'IsPriority' && args[0]) needs.priority = args[0].toUpperCase();
        else if (fn === 'MatchHeadline' && args[0]) needs.headline = args[0];
        else if (fn === 'IsPartOfProject' || fn === 'IsProject' || fn === 'InTagGroup') {
            needs.notes.push(`${fn}(${args.map(a => `"${a}"`).join(', ')}) - put beside a task that already passes it`);
        }
    };
    visit(query || '', false);
    return needs;
}

// --- dates the way they are typed -------------------------------------------

const WEEKDAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];

// A day from what somebody typed: today, tomorrow, a weekday (the next one,
// today included), +3d / +2w / +1m / -2d, 2026-10-12 or 10-12 (this year, or
// next once it has passed). Null when it is none of those.
export function parseWhen(s: string, now: Date = new Date()): Date | null {
    const t = s.trim().toLowerCase();
    const today = startOfDay(now);
    const plus = (days: number, months = 0) =>
        new Date(today.getFullYear(), today.getMonth() + months, today.getDate() + days);
    if (t === 'today' || t === 'tod' || t === 'now') return today;
    if (t === 'tomorrow' || t === 'tom') return plus(1);
    if (t === 'yesterday') return plus(-1);
    const wd = WEEKDAYS.findIndex(w => t.startsWith(w) && 'sunday monday tuesday wednesday thursday friday saturday'.indexOf(t) >= 0);
    if (wd >= 0 && t.length >= 3) return plus((wd - today.getDay() + 7) % 7);
    let m = t.match(/^([+-])(\d+)([dwm])?$/);
    if (m) {
        const n = Number(m[2]) * (m[1] === '-' ? -1 : 1);
        if (m[3] === 'w') return plus(n * 7);
        if (m[3] === 'm') return plus(0, n);
        return plus(n);
    }
    m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
    if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
    m = t.match(/^(\d{1,2})-(\d{1,2})$/);
    if (m) {
        let d = new Date(today.getFullYear(), Number(m[1]) - 1, Number(m[2]));
        if (d < today) d = new Date(today.getFullYear() + 1, Number(m[1]) - 1, Number(m[2]));
        return d;
    }
    return null;
}

// --- the line ---------------------------------------------------------------

export interface QuickLine {
    headline: string;
    status: string;
    tags: string[];
    person: string;
    // As typed, for EFFORT: "3d", "1.5d", "2w", "4h".
    effort: string;
    start: Date | null;
    // What the task waits on, as typed after ">".
    after: string;
    priority: string;
    props: Record<string, string>;
}

const COMMON_STATUSES = ['TODO', 'NEXT', 'DOING', 'IN-PROGRESS', 'WAITING', 'BLOCKED', 'DONE'];

// A token's underscores are spaces: @Ian_Davids is the person "Ian Davids",
// >design_review the task "design review".
const spaced = (s: string) => s.replace(/_/g, ' ').trim();

export function parseQuickAdd(line: string, statuses: string[] = [], now: Date = new Date()): QuickLine {
    const out: QuickLine = {
        headline: '', status: '', tags: [], person: '', effort: '', start: null, after: '', priority: '', props: {},
    };
    const known = new Set([...statuses, ...COMMON_STATUSES]);
    const words: string[] = [];
    // A quoted run is one token, so @"Ian Davids" and >"design review" work.
    const tokens = line.match(/[@>#^]?"[^"]*"|\S+/g) || [];
    tokens.forEach((raw, i) => {
        const tok = raw.replace(/^([@>#^]?)"([^"]*)"$/, '$1$2');
        if (i === 0 && known.has(tok)) { out.status = tok; return; }
        if (/^#[^\s#]+$/.test(tok)) {
            tok.slice(1).split(':').filter(Boolean).forEach(t => { if (out.tags.indexOf(t) < 0) out.tags.push(t); });
            return;
        }
        if (/^@.+/.test(tok)) { out.person = spaced(tok.slice(1)); return; }
        if (/^\^.+/.test(tok)) {
            const d = parseWhen(tok.slice(1), now);
            if (d) { out.start = d; return; }
        }
        if (/^>.+/.test(tok)) { out.after = spaced(tok.slice(1)); return; }
        if (/^![A-Za-z]$/.test(tok)) { out.priority = tok.slice(1).toUpperCase(); return; }
        if (/^\d+(\.\d+)?[hdwm]$/i.test(tok)) { out.effort = tok.toLowerCase(); return; }
        const kv = tok.match(/^([A-Za-z_][\w-]*)=(.+)$/);
        if (kv) { out.props[kv[1].toUpperCase()] = spaced(kv[2]); return; }
        words.push(raw);
    });
    out.headline = words.join(' ').trim();
    return out;
}

// --- filling it out ---------------------------------------------------------

export interface QuickContext {
    // Every task on the chart, to place the new one beside and to borrow
    // values the query wants from.
    tasks: GanttTask[];
    // The task the new one goes beside (and, for N, after).
    anchor: GanttTask | null;
    // Put the new task straight after the anchor (the N key), waiting on it.
    followAnchor?: boolean;
    personProp: string;
    // The property the chart's lanes are split by, if any: the new task goes
    // in the anchor's lane.
    laneProp: string;
    statuses: string[];
    now?: Date;
}

export interface QuickPlan {
    add: {
        ParentHash?: string;
        Filename?: string;
        Headline: string;
        Status: string;
        Start?: string;
        DateKind?: string;
        Effort: string;
        Tags: string[];
        Props: Record<string, string>;
    };
    // The task it waits on, when there is one: AFTER needs that task's id,
    // which the page may have to give it first.
    after: GanttTask | null;
    // What was filled in for the query, said in words for the preview.
    filled: string[];
    warnings: string[];
}

// The value most tasks on the chart have for a property, that also passes the
// query's test for it.
function commonValue(tasks: GanttTask[], name: string, re: string): string {
    let test: RegExp | null = null;
    try { test = re ? new RegExp(re) : null; } catch { test = null; }
    const count = new Map<string, number>();
    for (const t of tasks) {
        const v = propOf(t.props, name).trim();
        if (!v || (test && !test.test(v))) continue;
        count.set(v, (count.get(v) || 0) + 1);
    }
    let best = '';
    let n = 0;
    count.forEach((c, v) => { if (c > n) { best = v; n = c; } });
    return best;
}

// The value to write for a person typed by name. When a task on the chart
// already names them, its value is used as it stands - jira writes ASSIGNED
// as "Ian Davids   [email][id]", and a bare "Ian Davids" beside those would
// be a different person to every lane and filter that reads the property.
export function personValue(tasks: GanttTask[], prop: string, typed: string): string {
    const want = typed.trim().toLowerCase();
    if (!want) return typed;
    let prefix = '';
    for (const t of tasks) {
        const raw = propOf(t.props, prop).trim();
        const name = personOf(raw).toLowerCase();
        if (!raw) continue;
        if (name === want) return raw;
        if (!prefix && name.startsWith(want)) prefix = raw;
    }
    return prefix || typed;
}

// The task a fuzzy name means: a whole-word match before a part-word one,
// the shortest name before a longer one.
export function findTask(tasks: GanttTask[], name: string): GanttTask | null {
    const want = name.trim().toLowerCase();
    if (!want) return null;
    const live = tasks.filter(t => !t.mark && !!t.hash);
    const exact = live.find(t => t.name.toLowerCase() === want);
    if (exact) return exact;
    const hits = live.filter(t => t.name.toLowerCase().indexOf(want) >= 0);
    if (hits.length === 0) return null;
    return hits.sort((a, b) => a.name.length - b.name.length)[0];
}

export function planQuickAdd(line: QuickLine, needs: QueryNeeds, ctx: QuickContext): QuickPlan {
    const filled: string[] = [];
    const warnings: string[] = [];
    const now = ctx.now || new Date();
    const live = ctx.tasks.filter(t => !t.mark && !t.implied && !!t.hash);

    // Beside the anchor, or failing one beside the tasks most of the chart
    // sits with: the heading most of them are under. Being a sibling is what
    // carries everything the query cannot say plainly - the project it is
    // part of, the tags it inherits, the file it is in.
    let anchor = ctx.anchor && !ctx.anchor.implied ? ctx.anchor : null;
    if (!anchor && live.length > 0) {
        const count = new Map<string, number>();
        live.forEach(t => count.set(t.parent || '', (count.get(t.parent || '') || 0) + 1));
        let best = '';
        let n = -1;
        count.forEach((c, p) => { if (c > n) { best = p; n = c; } });
        anchor = live.find(t => (t.parent || '') === best) || live[0];
    }

    let status = line.status || needs.status;
    if (!status) {
        const active = ctx.statuses.find(s => s === 'TODO') || ctx.statuses[0] || 'TODO';
        status = active;
        if (needs.todo) filled.push(`keyword ${status} (the query wants todos)`);
    } else if (!line.status && needs.status) {
        filled.push(`keyword ${status} (the query asks for it)`);
    }

    const tags = line.tags.filter(t => needs.notTags.indexOf(t) < 0);
    for (const t of line.tags) if (needs.notTags.indexOf(t) >= 0) warnings.push(`the query leaves out :${t}:, so it was dropped`);
    for (const t of needs.tags) {
        if (tags.indexOf(t) >= 0) continue;
        // The anchor is on the chart, so it passes the query; if the tag is
        // not its own it is inherited (from a parent, or the file), and a
        // sibling inherits it the same way. Writing it again would only be
        // noise in the file.
        if (anchor && !anchor.implied && (anchor.tags || []).indexOf(t) < 0) continue;
        tags.push(t);
        filled.push(`tag :${t}:`);
    }

    const props: Record<string, string> = { ...line.props };
    if (line.person) props[ctx.personProp || 'ASSIGNED'] = personValue(live, ctx.personProp || 'ASSIGNED', line.person);
    for (const p of needs.props) {
        if (propOf(props, p.name)) continue;
        const lit = p.re ? literalOf(p.re) : null;
        const fromAnchor = anchor ? propOf(anchor.props, p.name).trim() : '';
        let test: RegExp | null = null;
        try { test = p.re ? new RegExp(p.re) : null; } catch { test = null; }
        const v = (fromAnchor && (!test || test.test(fromAnchor)) ? fromAnchor : '')
            || lit || commonValue(live, p.name, p.re);
        if (v) {
            props[p.name] = v;
            filled.push(`${p.name}=${v}`);
        } else {
            warnings.push(`the query needs ${p.name}${p.re ? ` matching /${p.re}/` : ''} and no task here has one to copy - add ${p.name}=...`);
        }
    }
    // The lane: the anchor's, when lanes are a property.
    if (ctx.laneProp && anchor && !propOf(props, ctx.laneProp)) {
        const v = propOf(anchor.props, ctx.laneProp).trim();
        if (v) { props[ctx.laneProp] = v; filled.push(`${ctx.laneProp}=${v} (the lane it goes in)`); }
    }

    let headline = line.headline;
    const priority = line.priority || needs.priority;
    if (priority) {
        headline = `[#${priority}] ${headline}`;
        if (!line.priority) filled.push(`priority ${priority}`);
    }
    if (needs.headline) {
        let ok = true;
        try { ok = new RegExp(needs.headline).test(line.headline); } catch { ok = true; }
        if (!ok) warnings.push(`the query only finds headlines matching /${needs.headline}/`);
    }
    needs.notes.forEach(n => warnings.push(`the query ${n}`));

    let after: GanttTask | null = null;
    if (line.after) {
        after = findTask(live, line.after);
        if (!after) warnings.push(`nothing on the chart is called "${line.after}"`);
    } else if (ctx.followAnchor && ctx.anchor) {
        after = ctx.anchor;
    }

    const add: QuickPlan['add'] = {
        Headline: headline,
        Status: status,
        Effort: line.effort || '1d',
        Tags: tags,
        Props: props,
    };
    if (anchor) {
        if (anchor.parent) add.ParentHash = anchor.parent;
        else add.Filename = anchor.filename;
    }
    // A date of its own when one was typed; otherwise one that waits on
    // something has none, and follows it - which is the point of waiting.
    if (line.start) {
        add.Start = dayKey(line.start);
        add.DateKind = 'SCHEDULED';
    } else if (!after) {
        add.Start = dayKey(startOfDay(now));
        add.DateKind = 'SCHEDULED';
    }
    if (!add.ParentHash && !add.Filename) warnings.push('nothing on the chart yet to say which file it belongs in');
    if (!line.headline) warnings.push('it needs a title');
    return { add, after, filled, warnings };
}
