// Changing the plan from the chart.
//
// Every edit a gantt renderer offers is one of these, and every one of them is
// an ordinary write to the org file behind the bar - a headline renamed, a
// SCHEDULED date moved, an EFFORT property set. Nothing here keeps a copy of
// the plan: the chart is refetched after a write, so what is drawn is what is
// in the file and a heading edited in the editor is right on the next refresh.
//
// The undo stack is the reason these are objects rather than calls. An op knows
// what it changed a value *from*, so taking it back is writing the old value
// again - and it knows what it changed the value *to*, which is what lets it
// refuse: if the heading no longer holds what this op left there, something
// else has happened since and putting the old value back would throw that away.
// That is the same rule the D&D sheet's undo uses, for the same reason.

import { ODb } from './db';
import { GanttTask, orgStamp, orgEffort, dayKey, parseGanttDate } from './gantt';

export interface GanttOp {
    // What the op did, in the words the toolbar shows: "Renamed Design the pages".
    label: string;
    apply: () => Promise<void>;
    revert: () => Promise<void>;
    // Reading the current value back off a freshly fetched task, so undo can
    // check nothing has moved underneath it. Undefined means the op cannot be
    // checked and is taken on trust (adding and deleting headings).
    read?: (t: GanttTask) => string;
    // What `read` should say if this op is still the last thing that happened.
    after?: string;
    // The heading this op is about, so undo can find it again.
    hash: string;
}

function fail(res: any, what: string) {
    // The server answers Ok:false with a message rather than an http error for
    // most of these, so a write that did nothing has to be looked for.
    if (res && res.Ok === false) throw new Error(res.Msg || `${what} failed`);
}

// --- the ops ---------------------------------------------------------------

export function renameOp(t: GanttTask, name: string): GanttOp {
    const was = t.name;
    const hash = t.hash as string;
    return {
        label: `Renamed "${was}" to "${name}"`,
        hash,
        apply: async () => fail(await ODb.renameHeadline(hash, name), 'rename'),
        revert: async () => fail(await ODb.renameHeadline(hash, was), 'rename'),
        read: x => x.name,
        after: name,
    };
}

export function statusOp(t: GanttTask, status: string): GanttOp {
    const was = t.status || '';
    const hash = t.hash as string;
    return {
        label: `${t.name}: ${was || 'no keyword'} → ${status || 'no keyword'}`,
        hash,
        apply: async () => fail(await ODb.changeStatus(hash, status), 'status'),
        revert: async () => fail(await ODb.changeStatus(hash, was), 'status'),
        read: x => x.status || '',
        after: status,
    };
}

// Moving a bar writes the heading's own date. Which date that is - SCHEDULED or
// a plain timestamp - is the one it already has; a heading with neither gets a
// SCHEDULED, because that is what org means by "this is when I will do it".
export function startOp(t: GanttTask, start: Date | null): GanttOp {
    const hash = t.hash as string;
    const kind = t.dateKind || 'SCHEDULED';
    const had = t.dated ? dayKey(t.start) : '';
    const now = start ? dayKey(start) : '';
    const write = async (day: string) => {
        if (day === '') {
            fail(await ODb.removeDate(hash, kind), 'clear date');
        } else {
            const d = parseGanttDate(day) as Date;
            fail(await ODb.changeDate(hash, kind, orgStamp(d)), 'set date');
        }
    };
    return {
        label: now ? `${t.name} starts ${now}` : `${t.name} has no date`,
        hash,
        apply: () => write(now),
        revert: () => write(had),
        read: x => (x.dated ? dayKey(x.start) : ''),
        after: now,
    };
}

// Dragging the end of a bar is an estimate, not a date: it writes EFFORT, which
// is where the length of a task lives in org. The bar may still come out wider
// than the effort when it steps over a weekend.
export function effortOp(t: GanttTask, days: number): GanttOp {
    const hash = t.hash as string;
    const was = t.effort || '';
    const now = orgEffort(days);
    return {
        label: `${t.name} takes ${now}`,
        hash,
        apply: async () => fail(await ODb.changeProperty(hash, 'EFFORT', now), 'effort'),
        revert: async () => fail(await ODb.changeProperty(hash, 'EFFORT', was), 'effort'),
        read: x => x.effort || '',
        after: now,
    };
}

export function propOp(t: GanttTask, name: string, value: string, label: string): GanttOp {
    const hash = t.hash as string;
    const was = (t.props || {})[name] || '';
    return {
        label,
        hash,
        apply: async () => fail(await ODb.changeProperty(hash, name, value), name),
        revert: async () => fail(await ODb.changeProperty(hash, name, was), name),
        read: x => ((x.props || {})[name] || ''),
        after: value,
    };
}

export function colorOp(t: GanttTask, color: string): GanttOp {
    return propOp(t, 'GANTT_COLOR', color, color ? `${t.name} is ${color}` : `${t.name} back to its lane colour`);
}

export function percentOp(t: GanttTask, percent: number): GanttOp {
    const p = Math.max(0, Math.min(100, Math.round(percent)));
    return propOp(t, 'PERCENTDONE', String(p), `${t.name} is ${p}% done`);
}

export function sectionOp(t: GanttTask, section: string): GanttOp {
    return propOp(t, 'SECTION', section, `${t.name} moved to ${section || 'no lane'}`);
}

export function orderOp(t: GanttTask, order: number): GanttOp {
    return propOp(t, 'GANTT_ORDER', String(order), `${t.name} reordered`);
}

// A property looked up the way the server matches it: without regard to case,
// because org writes names in either and `setHeadingProperty` replaces or
// removes a line whatever its case.
export function propValue(props: Record<string, string> | undefined, name: string): string {
    const p = props || {};
    if (name in p) return p[name] || '';
    const k = Object.keys(p).find(k => k.toUpperCase() === name.toUpperCase());
    return k ? p[k] || '' : '';
}

// A property name org will read back: no spaces, no colons, not empty.
// (`+` on the end is org's "append to the inherited value", and is allowed.)
export function propNameError(name: string): string {
    if (!name) return 'a property needs a name';
    if (/[\s:]/.test(name)) return 'a property name has no spaces or colons';
    return '';
}

// Setting, changing or removing one property. An empty value removes it,
// which is what the server does with an empty write; undo writes the old value
// back, so a removed property returns - at the end of the drawer rather than
// where it was, since the drawer is edited a line at a time.
export function setPropOp(t: GanttTask, name: string, value: string): GanttOp {
    const hash = t.hash as string;
    const was = propValue(t.props, name);
    const label = value === ''
        ? `${t.name}: removed ${name}`
        : was === '' ? `${t.name}: added ${name} = ${value}` : `${t.name}: ${name} = ${value}`;
    return {
        label,
        hash,
        apply: async () => fail(await ODb.changeProperty(hash, name, value), name),
        revert: async () => fail(await ODb.changeProperty(hash, name, was), name),
        read: x => propValue(x.props, name),
        after: value,
    };
}

// Renaming a property is a remove and an add, run as one undo, optionally
// with a new value as well. The add goes last so the stack checks the new name
// when it is asked to take it back.
export function renamePropOp(t: GanttTask, from: string, to: string, value?: string): GanttOp[] {
    const v = value === undefined ? propValue(t.props, from) : value;
    const add = setPropOp(t, to, v);
    return [setPropOp(t, from, ''), { ...add, label: `${t.name}: ${from} renamed ${to}` }];
}

// Tags are written as the heading's whole list, as a line edit of the headline
// alone (`/heading/parts`), so undo is writing the old list back - order and all.
export function tagsOp(t: GanttTask, tags: string[]): GanttOp {
    const hash = t.hash as string;
    const was = [...(t.tags || [])];
    const now = tags.map(x => x.trim().replace(/^:+|:+$/g, '')).filter(Boolean);
    const added = now.filter(x => was.indexOf(x) < 0);
    const removed = was.filter(x => now.indexOf(x) < 0);
    const said = [...added.map(x => `+:${x}:`), ...removed.map(x => `-:${x}:`)].join(' ');
    return {
        label: `${t.name}: tags ${said || 'reordered'}`,
        hash,
        apply: async () => fail(await ODb.setHeadingParts(hash, { Tags: now }), 'tags'),
        revert: async () => fail(await ODb.setHeadingParts(hash, { Tags: was }), 'tags'),
        read: x => (x.tags || []).join(':'),
        after: now.join(':'),
    };
}

// A tag name org will read: letters, digits, `_`, `@`, `#` and `%`.
export function tagError(tag: string): string {
    const t = tag.trim().replace(/^:+|:+$/g, '');
    if (!t) return '';
    if (!/^[\p{L}\p{N}_@#%]+$/u.test(t)) return 'a tag is letters, digits, _ @ # or %';
    return '';
}

// The step between two rows. Wide enough that a later move can be written as a
// value between two neighbours if it ever needs to be, though the rewrite below
// does not bother: renumbering a lane is a handful of writes and is always
// consistent, where fractional values drift and eventually collide.
export const ORDER_STEP = 10;

// Give a lane the order it is now in. Only the rows whose number actually
// changes are written, so moving one row among rows that already have orders
// costs one or two writes - but a lane where nobody has an order yet is written
// out in full, once, and is well behaved from then on.
//
// The whole lot comes back as one list so the page can run it as a single
// undoable move rather than as N separate ones.
export function reorderOps(laneInNewOrder: GanttTask[]): GanttOp[] {
    const ops: GanttOp[] = [];
    laneInNewOrder.forEach((t, i) => {
        if (!t.hash || t.implied) return;
        const want = (i + 1) * ORDER_STEP;
        if (t.order === want) return;
        ops.push(orderOp(t, want));
    });
    return ops;
}

// A dependency is org's AFTER property, which names an *id* rather than a hash -
// so the heading being depended on needs one, and is given one if it has none.
// That write is part of the op and is taken back with it.
export function dependencyOp(t: GanttTask, dep: GanttTask | null): {
    op: GanttOp;
    // The id write, when one was needed. Run before the op and reverted after it.
    ensureId?: GanttOp;
} {
    const hash = t.hash as string;
    const was = (t.props || {})['AFTER'] || '';
    if (!dep) {
        return {
            op: {
                label: `${t.name} no longer waits on anything`,
                hash,
                apply: async () => fail(await ODb.changeProperty(hash, 'AFTER', ''), 'dependency'),
                revert: async () => fail(await ODb.changeProperty(hash, 'AFTER', was), 'dependency'),
                read: x => ((x.props || {})['AFTER'] || ''),
                after: '',
            },
        };
    }
    const depProps = dep.props || {};
    const existing = depProps['ID'] || depProps['CUSTOM_ID'] || '';
    const id = existing || idFor(dep);
    const op: GanttOp = {
        label: `${t.name} comes after ${dep.name}`,
        hash,
        apply: async () => fail(await ODb.changeProperty(hash, 'AFTER', id), 'dependency'),
        revert: async () => fail(await ODb.changeProperty(hash, 'AFTER', was), 'dependency'),
        read: x => ((x.props || {})['AFTER'] || ''),
        after: id,
    };
    if (existing) return { op };
    const depHash = dep.hash as string;
    return {
        op,
        ensureId: {
            label: `Gave ${dep.name} an id`,
            hash: depHash,
            apply: async () => fail(await ODb.changeProperty(depHash, 'ID', id), 'id'),
            revert: async () => fail(await ODb.changeProperty(depHash, 'ID', ''), 'id'),
            read: x => ((x.props || {})['ID'] || ''),
            after: id,
        },
    };
}

// A readable id for a heading that has none: its own words, plus enough of its
// hash to keep two headings with the same name apart.
export function idFor(t: GanttTask): string {
    const slug = t.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 24) || 'task';
    const tail = (t.hash || '').replace(/[^a-zA-Z0-9]/g, '').slice(0, 6).toLowerCase();
    return tail ? `${slug}-${tail}` : slug;
}

// Deleting takes the whole heading. Undo puts the words back - as a new heading
// with a new hash, which is honest about what it is: the file is as it was, but
// nothing that pointed at the old hash knows that.
export function deleteOp(t: GanttTask, onUndone?: () => void): GanttOp {
    const hash = t.hash as string;
    const body = {
        ParentHash: t.parent || undefined,
        Filename: t.parent ? undefined : t.filename,
        Headline: t.name,
        Status: t.status || '',
        Start: t.dated ? dayKey(t.start) : '',
        DateKind: t.dateKind || 'SCHEDULED',
        Effort: t.effort || '',
        Tags: t.tags || [],
        Props: { ...(t.props || {}) },
    };
    delete (body.Props as Record<string, string>)['EFFORT'];
    return {
        label: `Deleted ${t.name}`,
        hash,
        apply: async () => {
            const res = await ODb.deleteEntry(hash);
            fail(res, 'delete');
        },
        revert: async () => {
            fail(await ODb.ganttAdd(body as any), 'restore');
            if (onUndone) onUndone();
        },
    };
}

export function addOp(add: {
    ParentHash?: string;
    Filename?: string;
    Headline: string;
    Status?: string;
    Start?: string;
    DateKind?: string;
    Effort?: string;
}, findHash: () => Promise<string | null>): GanttOp {
    return {
        label: `Added ${add.Headline}`,
        hash: '',
        apply: async () => fail(await ODb.ganttAdd(add), 'add'),
        revert: async () => {
            // The new heading's hash is not known until the server has reread
            // the file, so undo looks it up rather than remembering it.
            const hash = await findHash();
            if (!hash) throw new Error('cannot find the task that was added - delete it by hand');
            fail(await ODb.deleteEntry(hash), 'delete');
        },
    };
}

// --- the stack -------------------------------------------------------------

export class UndoStack {
    private ops: GanttOp[] = [];
    // What undo took back, newest last, for redo. Anything new that happens
    // empties it: redoing past a change made since would be redoing onto a
    // plan that is no longer the one it was undone from.
    private undone: GanttOp[] = [];
    // How many are kept. An evening of planning, not a record.
    constructor(private limit: number = 50) { }

    push(op: GanttOp) {
        this.ops.push(op);
        if (this.ops.length > this.limit) this.ops.shift();
        this.undone = [];
    }

    get redoDepth(): number {
        return this.undone.length;
    }

    peekRedo(): GanttOp | null {
        return this.undone.length > 0 ? this.undone[this.undone.length - 1] : null;
    }

    // Do again what undo took back. It goes back on the undo stack, so undo
    // and redo can be pressed back and forth.
    async redo(): Promise<string> {
        const op = this.undone.pop();
        if (!op) throw new Error('nothing to redo');
        try {
            await op.apply();
        } catch (e) {
            this.undone.push(op);
            throw e;
        }
        this.ops.push(op);
        return op.label;
    }

    get depth(): number {
        return this.ops.length;
    }

    peek(): GanttOp | null {
        return this.ops.length > 0 ? this.ops[this.ops.length - 1] : null;
    }

    // Take the last op back, having first checked that it really is the last
    // thing that happened to that heading. `current` is the task as the server
    // describes it now, or null when it has gone.
    async undo(current: (hash: string) => GanttTask | null): Promise<string> {
        const op = this.ops.pop();
        if (!op) throw new Error('nothing to undo');
        if (op.read && op.after !== undefined) {
            const t = op.hash ? current(op.hash) : null;
            if (!t) {
                this.ops.push(op);
                throw new Error('that task is no longer in the chart');
            }
            if (op.read(t) !== op.after) {
                this.ops.push(op);
                throw new Error(`"${t.name}" has changed since then - undo would throw that away`);
            }
        }
        try {
            await op.revert();
        } catch (e) {
            this.ops.push(op);
            throw e;
        }
        this.undone.push(op);
        return op.label;
    }

    clear() {
        this.ops = [];
        this.undone = [];
    }
}
