// A block of text, coloured as code.
//
// The Files tab colours code because it is inside an org file and the org
// highlighter walks it on the way past. This is the same colouring with
// nothing around it, for text that arrived on its own: the contents of a file
// a source block produced.
//
// The colours are the org theme's, the same as everywhere else - a mermaid
// file shown under a block in a Solarized file looks like Solarized.

import * as React from 'react';
import Box from '@mui/joy/Box';
import { useColorScheme } from '@mui/joy/styles';
import { orgPalette } from '../orgtheme';
import { useSetting } from '../useSettings';
import { hlLine, langSpec, newHlState, isKnownLang, KIND_ROLE } from '../codehl';

export default function CodeText({
    text,
    lang = '',
    maxHeight = 320,
    gutter = true,
}: {
    text: string;
    lang?: string;
    maxHeight?: number | string;
    // Line numbers. Worth having for a file being read, not worth it for two
    // lines of output.
    gutter?: boolean;
}) {
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';
    const [themeKey] = useSetting('orgTheme');
    const p = orgPalette(themeKey, dark);

    const lines = React.useMemo(() => text.replace(/\r\n/g, '\n').split('\n'), [text]);

    // Scanned in one pass so the state carries: a docstring or a block comment
    // that opens on one line has to still be open on the next.
    const painted = React.useMemo(() => {
        if (!isKnownLang(lang)) return null;
        const spec = langSpec(lang);
        const st = newHlState();
        return lines.map(l => hlLine(l, spec, st));
    }, [lines, lang]);

    const width = String(lines.length).length;

    return (
        <Box
            sx={{
                background: p.bg,
                color: p.fg,
                borderRadius: 'sm',
                overflow: 'auto',
                maxHeight,
                fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
                fontSize: 12,
                lineHeight: 1.55,
                py: 0.75,
            }}
        >
            {lines.map((line, i) => (
                <Box key={i} sx={{ display: 'flex', minWidth: 'max-content' }}>
                    {gutter && (
                        <Box
                            component="span"
                            sx={{
                                color: p.gutter, background: p.gutterBg,
                                px: 1, textAlign: 'right', userSelect: 'none',
                                minWidth: `${width + 1}ch`, flexShrink: 0,
                            }}
                        >
                            {i + 1}
                        </Box>
                    )}
                    <Box component="span" sx={{ px: 1.25, whiteSpace: 'pre', flex: 1 }}>
                        {painted
                            ? painted[i].map((s, j) => (
                                <span key={j} style={{ color: p[KIND_ROLE[s.kind]] || p.fg }}>{s.text}</span>
                            ))
                            : line}
                    </Box>
                </Box>
            ))}
        </Box>
    );
}
